-- ============================================================
-- 090 — Quick Guide infographics: every remaining card (Randy, Sept 23 2026)
--
-- Randy approved the pilot (088/089) and asked for the rest. This fills
-- the other 110 cards across 13 topics with drawn infographics — each one
-- carrying the card's points and heads-up, a "why it matters" line, and a
-- real-shift example where it helps. The 13 cards in "Things Most People
-- Don't Know" reuse the graphic of the same card in its home topic.
--
-- Every spec was checked against its source card (nothing dropped, may /
-- will / must kept as written, no invented numbers), validated for shape
-- and bilingual text, and rendered in English and Spanish before shipping.
--
-- The Quick Guide is still preview-only, so only the owner sees these until
-- topics are published. Safe to run more than once. The last statement
-- prints the result.
-- ============================================================


-- ════════ Things Most People Don’t Know ════════

-- Never clock in for someone else.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Clock in and out only for yourself","es":"Marca entrada y salida solo por ti"}],"dont":[{"en":"Clock in for anyone else","es":"Marcar entrada por otra persona"},{"en":"Let anyone clock in for you","es":"Dejar que alguien marque entrada por ti"}],"note":{"en":"This is time fraud — it can mean immediate termination.","es":"Esto es fraude de tiempo — puede significar terminación inmediata."},"noteTone":"warn","why":{"en":"Your punch is your word about when you worked — it only means something if it's yours alone.","es":"Tu registro es tu palabra sobre cuándo trabajaste — solo vale si es únicamente tuyo."},"example":{"en":"A teammate running late texts you to punch them in? Say no — they clock in when they get there.","es":"¿Un compañero que viene tarde te escribe para que marques por él? Di que no — él marca entrada cuando llegue."}}$IG$::jsonb, updated_at = now() where id = '1ab265e8-25b4-4b0c-9904-e797d094ba27';

-- 12 clean months can reset a written warning.
update handbook_cards set infographic = $IG${"type":"stat","value":"12","unit":{"en":"months","es":"meses"},"segments":12,"label":{"en":"in a row, same issue never repeated","es":"seguidos, sin repetir el mismo problema"},"sub":{"en":"Do that and a written warning can come off your record. Managers track it — and real progress shows in your evaluation.","es":"Si lo logras, una advertencia escrita puede salir de tu historial. Los gerentes lo registran — y el progreso real se nota en tu evaluación."},"why":{"en":"We care about your pattern, not one mistake held against you forever.","es":"Nos importa tu patrón, no un error que te persiga para siempre."},"example":{"en":"Written warning in March. Clean through the next March — and it can come off.","es":"Advertencia escrita en marzo. Limpio hasta el siguiente marzo — y puede salir de tu historial."}}$IG$::jsonb, updated_at = now() where id = '1aa8b94a-7bf5-44fe-9b2b-330d7fc872bf';

-- Ring every meal into the POS before you take a bite.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Any discount level","es":"Cualquier nivel de descuento"},{"en":"Any position","es":"Cualquier posición"},{"en":"Managers included","es":"Gerentes incluidos"}],"badge":{"en":"Every meal","es":"Cada comida"},"note":{"en":"Abusing the meal benefit may cost you the privilege — plus further disciplinary action.","es":"Abusar del beneficio de comida puede costarte el privilegio — además de acción disciplinaria adicional."},"noteTone":"warn","why":{"en":"Ringing in every meal protects food cost, inventory accuracy, and fairness across the team.","es":"Ingresar cada comida protege el costo de alimentos, la precisión del inventario y la equidad en el equipo."},"example":{"en":"Even a manager's free shift meal gets rung into the POS before the first bite.","es":"Hasta la comida de turno gratis de un gerente se ingresa al POS antes del primer bocado."}}$IG$::jsonb, updated_at = now() where id = '447f67b8-6aa3-4b91-b802-7c8c4d6677e9';

-- Over 40 hours in a workweek? That’s overtime at 1.5×.
update handbook_cards set infographic = $IG${"type":"stat","value":"1.5×","label":{"en":"your regular rate, per overtime hour","es":"tu tarifa regular, por cada hora extra"},"sub":{"en":"For non-exempt hourly employees, on every hour over 40. Overtime is calculated weekly — and must be pre-approved by management.","es":"Para empleados por hora no exentos, por cada hora arriba de 40. Las horas extra se calculan por semana — y deben ser pre-aprobadas por la gerencia."},"icon":"clock","footer":{"tone":"warn","text":{"en":"Unauthorized overtime is handled as a conduct issue — but you'll always be paid for every hour you work.","es":"Las horas extra no autorizadas se tratan como un problema de conducta — pero siempre se te paga por cada hora trabajada."}},"why":{"en":"Overtime costs 50% more per hour, so it has to be planned ahead — not discovered on payday.","es":"Las horas extra cuestan 50% más por hora, así que hay que planearlas — no descubrirlas el día de pago."},"example":{"en":"38 hours one week, 44 the next? Only the 4 hours past 40 in the second week are overtime.","es":"¿38 horas una semana y 44 la siguiente? Solo las 4 horas arriba de 40 de la segunda semana son horas extra."}}$IG$::jsonb, updated_at = now() where id = 'c17c1d91-6993-488d-a60a-c31a01db3757';

-- Wear a clean, unwrinkled uniform in good condition every shift.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"The Company","es":"La Compañía"},"icon":"gift","lines":[{"en":"Provides your first uniforms","es":"Te da tus primeros uniformes"},{"en":"Details what to wear in your position training materials","es":"Detalla qué usar en tus materiales de capacitación de posición"}]},"right":{"title":{"en":"You","es":"Tú"},"icon":"shirt","lines":[{"en":"Keep them clean, unwrinkled, and in good condition","es":"Mantenerlos limpios, sin arrugas y en buen estado"},{"en":"Wear what your position and location call for","es":"Usar lo que corresponde a tu posición y ubicación"}]},"note":{"en":"Show up out of uniform and you may be sent home to fix it — that time isn't paid.","es":"Si llegas sin uniforme, te pueden enviar a casa a corregirlo — y ese tiempo no se paga."},"noteTone":"warn","why":{"en":"Guests notice the details before they taste the food — a sharp uniform tells them we care.","es":"Los clientes notan los detalles antes de probar la comida — un uniforme impecable les dice que nos importa."},"example":{"en":"Spilled broth on your shirt Friday night? Wash it before Saturday's shift — upkeep is on you.","es":"¿Se te cayó caldo en la camisa el viernes en la noche? Lávala antes de tu turno del sábado — mantenerla te toca a ti."}}$IG$::jsonb, updated_at = now() where id = '310a7488-30df-4c5d-8db6-630d7238587b';

-- No scheduled breaks during peak: 11:30am–1:30pm and 5:30pm–8:30pm.
update handbook_cards set infographic = $IG${"type":"day","from":"10:00","to":"22:00","blocks":[{"start":"11:30","end":"13:30"},{"start":"17:30","end":"20:30"}],"blockLabel":{"en":"Peak — no scheduled breaks","es":"Hora pico — sin descansos programados"},"openLabel":{"en":"Outside peak hours, breaks happen at manager-approved times.","es":"Fuera de las horas pico, los descansos son en horarios aprobados por el gerente."},"note":{"en":"Urgent restroom need or genuine emergency? Notify the manager on duty. Five minutes is expected; ten is the absolute maximum.","es":"¿Necesidad urgente de ir al baño o una emergencia genuina? Avísale al gerente en turno. Se esperan cinco minutos; diez es el máximo absoluto."},"noteTone":"info","why":{"en":"Peak hours are when guests need all of us — one missing person is felt across the whole floor.","es":"Las horas pico son cuando los clientes nos necesitan a todos — una persona menos se siente en todo el piso."},"example":{"en":"Working 4 to 10? Any scheduled break falls before 5:30 or after 8:30, at a time your manager approves.","es":"¿Trabajas de 4 a 10? Cualquier descanso programado es antes de las 5:30 o después de las 8:30, a la hora que apruebe tu gerente."}}$IG$::jsonb, updated_at = now() where id = '088b995a-c832-4cc6-b7b5-b6c930a2e0cd';

-- Your 7shifts schedule stands unless a manager confirms changes in writing.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Verbal conversation","es":"Conversación verbal"},"icon":"chat","lines":[{"en":"Doesn't override 7shifts","es":"No anula lo publicado en 7shifts"},{"en":"Your posted shift still stands","es":"Tu turno publicado se mantiene"}]},"right":{"title":{"en":"Manager confirms in writing","es":"Un gerente confirma por escrito"},"icon":"check","lines":[{"en":"Now the change counts","es":"Ahora el cambio cuenta"}]},"note":{"en":"Agreed on a change? Make sure a manager confirms it in writing.","es":"¿Acordaron un cambio? Asegúrate de que un gerente lo confirme por escrito."},"why":{"en":"Written confirmation keeps you, your teammates, and your manager working from the same schedule.","es":"La confirmación por escrito hace que tú, tus compañeros y tu gerente trabajen con el mismo horario."},"example":{"en":"A manager says “sure, leave at 8” in passing? Until it's confirmed in writing, your 7shifts shift still stands.","es":"¿Un gerente te dice de pasada “sí, vete a las 8”? Hasta que lo confirme por escrito, tu turno en 7shifts se mantiene."}}$IG$::jsonb, updated_at = now() where id = '3b72e633-6707-4725-9e52-32dc66fafacf';

-- Time alone doesn’t raise your pay — consistent value does.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"A raise is","es":"Un aumento es"},"icon":"growth","lines":[{"en":"An investment","es":"Una inversión"},{"en":"We believe you consistently produce value that justifies higher pay","es":"Creemos que produces valor constantemente a un nivel que justifica un pago más alto"}]},"right":{"title":{"en":"A raise isn't","es":"Un aumento no es"},"icon":"x","lines":[{"en":"On a set calendar","es":"Según un calendario fijo"},{"en":"Just because time has passed","es":"Solo porque ha pasado el tiempo"},{"en":"A sympathy adjustment","es":"Un ajuste por simpatía"},{"en":"A reward for asking confidently","es":"Una recompensa por pedirlo con confianza"}]},"note":{"en":"Longevity is respected — it just isn't a raise on its own.","es":"La antigüedad se respeta — pero por sí sola no es un aumento."},"noteTone":"info","why":{"en":"Pay is how we invest in the people who make every shift better, so it follows the value you bring.","es":"El pago es cómo invertimos en las personas que mejoran cada turno, así que sigue el valor que aportas."},"example":{"en":"Two years on the job doesn't trigger a raise by itself — consistently running a clean, fast station is what makes the case.","es":"Dos años en el puesto no generan un aumento por sí solos — mantener tu estación limpia y rápida de forma constante es lo que lo justifica."}}$IG$::jsonb, updated_at = now() where id = 'ddbdab92-c31f-4d06-ac74-c0d04ae90efb';

-- With harassment, impact matters more than intent.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Words","es":"Palabras"},"icon":"chat","lines":[{"en":"Slurs or offensive jokes","es":"Insultos o chistes ofensivos"},{"en":"Insulting nicknames or threats","es":"Apodos despectivos o amenazas"},{"en":"Unwanted comments about protected characteristics","es":"Comentarios no deseados sobre características protegidas"}]},"right":{"title":{"en":"Visual & physical","es":"Visual y física"},"icon":"hand","lines":[{"en":"Offensive images, gestures, or written material","es":"Imágenes ofensivas, gestos o material escrito"},{"en":"Unwanted touching or blocking someone's way","es":"Contacto no deseado o bloquearle el paso a alguien"},{"en":"Any physical aggression","es":"Cualquier agresión física"}]},"note":{"en":"Mockery and persistent unwanted attention count too. Saying you didn't mean it doesn't change it — harassment counts regardless of intent.","es":"Las burlas y la atención persistente no deseada también cuentan. Decir que no fue tu intención no lo cambia — el acoso cuenta independientemente de la intención."},"noteTone":"warn","why":{"en":"Everyone here deserves to feel safe at work, and it's the person on the receiving end who lives with the impact.","es":"Todos aquí merecen sentirse seguros en el trabajo, y es la persona que lo recibe quien vive con el impacto."},"example":{"en":"A nickname that mocks a coworker's accent counts — even if you meant it as a joke.","es":"Un apodo que se burla del acento de un compañero cuenta — aunque lo hayas dicho en broma."}}$IG$::jsonb, updated_at = now() where id = 'a2164cbe-221c-4bd4-a2e7-1d78191b2800';

-- Guest gets hurt? Get the manager — don’t admit fault.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Notify the manager on duty immediately","es":"Notifica al gerente en turno inmediatamente"}],"dont":[{"en":"Admit fault","es":"Admitir culpa"},{"en":"Make statements about liability","es":"Hacer declaraciones sobre responsabilidad"}],"why":{"en":"The manager on duty takes it from there — a well-meant “that was our fault” can create liability questions for the Company.","es":"El gerente en turno se encarga a partir de ahí — un “fue nuestra culpa” bien intencionado puede crear problemas de responsabilidad para la Compañía."},"example":{"en":"A guest trips near the host stand? Get the manager right away — you can ask “Are you okay?” but don't say “That's our fault.”","es":"¿Un cliente se tropieza cerca de la recepción? Busca al gerente de inmediato — puedes preguntar “¿Está bien?” pero no digas “Es nuestra culpa.”"}}$IG$::jsonb, updated_at = now() where id = '7f07139b-4c6c-4e04-aa7d-4174854362d2';

-- Taking a medication that could affect alertness? Tell a manager first.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Check your prescription","es":"Revisa tu medicamento recetado"},"sub":{"en":"Could it affect your alertness or coordination?","es":"¿Podría afectar tu estado de alerta o coordinación?"}},{"title":{"en":"If so, tell a manager","es":"Si es así, avísale a un gerente"},"sub":{"en":"Before your shift begins","es":"Antes de que comience tu turno"}}],"why":{"en":"A manager can only plan around what they know — a quick heads-up helps keep you and your teammates safe.","es":"Un gerente solo puede planear con lo que sabe — un aviso rápido ayuda a mantenerte seguro a ti y a tus compañeros."},"example":{"en":"Started a new prescription that makes you drowsy? Tell a manager before your shift starts, not halfway through it.","es":"¿Empezaste un medicamento recetado que te da sueño? Avísale a un gerente antes de que empiece tu turno, no a la mitad."}}$IG$::jsonb, updated_at = now() where id = '251b8dec-8d24-4634-8973-2c1be90b4bfd';

-- In your first 90 days, standard discipline steps may not apply.
update handbook_cards set infographic = $IG${"type":"icon","icon":"clock","phrase":{"en":"Built to catch fit issues early","es":"Hecho para detectar problemas de compatibilidad temprano"},"sub":{"en":"For your benefit and ours.","es":"Para tu beneficio y el nuestro."},"note":{"en":"Not meeting expectations? You may be separated without going through the standard disciplinary process.","es":"¿No estás cumpliendo con las expectativas? Pueden separarte del empleo sin pasar por el proceso disciplinario estándar."},"noteTone":"warn","why":{"en":"If it's not the right fit, it's better for both sides to recognize that early than to drag it out.","es":"Si no es la opción correcta, es mejor para ambos lados reconocerlo temprano que alargarlo."}}$IG$::jsonb, updated_at = now() where id = '63a844ff-76b8-45ad-92d7-1b2a9654492a';

-- Your job isn’t done until the whole team is caught up.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Jump in when a teammate is underwater","es":"Ayuda cuando un compañero está ahogado de trabajo"},{"en":"See what needs to be done — and do it","es":"Ve lo que hay que hacer — y hazlo"},{"en":"Anticipate needs — help before teammates have to ask","es":"Anticipa las necesidades — ayuda antes de que tus compañeros tengan que pedirlo"}],"dont":[{"en":"Stop because your own section is covered","es":"Detenerte porque tu sección ya está cubierta"},{"en":"Wait to be told","es":"Esperar a que te lo digan"}],"why":{"en":"Guests don't see sections — they see one team. When one of us falls behind, the whole room feels it.","es":"Los clientes no ven secciones — ven un solo equipo. Cuando uno de nosotros se atrasa, todo el salón lo siente."},"example":{"en":"Your tables are set and a teammate just got three tables at once? Run their drinks or bus their tables — before they ask.","es":"¿Tus mesas están listas y a un compañero le sentaron tres mesas a la vez? Lleva sus bebidas o recoge sus mesas — antes de que te lo pida."}}$IG$::jsonb, updated_at = now() where id = '0fae7c50-f4af-499b-94ab-0878566ee74f';


-- ════════ Clocking In & Out ════════

-- Clock in no more than 7 minutes early.
update handbook_cards set infographic = $IG${"type":"stat","value":"7","unit":{"en":"min","es":"min"},"label":{"en":"The early clock-in limit","es":"El límite para marcar temprano"},"sub":{"en":"Clock in and out on your location's 7Punches iPad station. Clock out as soon as your shift and duties are done.","es":"Marca entrada y salida en la estación de iPad de tu ubicación (7Punches). Marca salida en cuanto terminen tu turno y tus tareas."},"icon":"clock","footer":{"tone":"warn","text":{"en":"Clocked in early without a manager's OK? It gets flagged and may be adjusted.","es":"¿Marcaste temprano sin el visto bueno de un gerente? Queda señalado y puede ajustarse."}},"why":{"en":"Seven minutes gives you time to get ready without adding hours the schedule didn't plan for.","es":"Siete minutos te dan tiempo para prepararte sin sumar horas que el horario no tenía previstas."},"example":{"en":"Shift starts at 4:00? Clock in no earlier than 3:53.","es":"¿Tu turno empieza a las 4:00? Marca entrada no antes de las 3:53."}}$IG$::jsonb, updated_at = now() where id = '9e459b89-e662-41ab-b548-a535dc4079fc';

-- Clock out for every break.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Clock out","es":"Marca salida"},"sub":{"en":"Before your break starts","es":"Antes de que empiece tu descanso"}},{"title":{"en":"Take your break","es":"Toma tu descanso"}},{"title":{"en":"Clock back in","es":"Vuelve a marcar entrada"},"sub":{"en":"When you return","es":"Cuando regreses"}}],"note":{"en":"Staying clocked in during a break is a timekeeping violation.","es":"Quedarte con el reloj marcado durante un descanso es una violación de control de tiempo."},"noteTone":"warn","why":{"en":"Your punches should match exactly when you're working — that keeps your hours, and your pay, accurate.","es":"Tus registros deben coincidir exactamente con el tiempo que trabajas — así tus horas y tu pago quedan correctos."}}$IG$::jsonb, updated_at = now() where id = 'e14cab05-dd78-44ef-bdde-869a7deec108';

-- Enter your tips before you leave.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Every shift","es":"En cada turno"},"icon":"cash","lines":[{"en":"Enter tips as you clock out","es":"Ingresa las propinas al marcar salida"},{"en":"On the 7Punches station","es":"En la estación de 7Punches"}]},"right":{"title":{"en":"Missed or entered wrong?","es":"¿Se te olvidaron o las ingresaste mal?"},"icon":"chat","lines":[{"en":"Tell your manager right away","es":"Avísale a tu gerente de inmediato"},{"en":"So it can be adjusted","es":"Para que se pueda ajustar"}]},"why":{"en":"Your tip entry is the record your pay is built on — the sooner a mistake is flagged, the easier it is to fix.","es":"Lo que ingresas de propinas es el registro con el que se arma tu pago — entre más pronto se reporte un error, más fácil es corregirlo."},"example":{"en":"Realize on the drive home you never entered your tips? Tell your manager right away so it can be adjusted.","es":"¿Te das cuenta camino a casa de que no ingresaste tus propinas? Avísale a tu gerente de inmediato para ajustarlo."}}$IG$::jsonb, updated_at = now() where id = 'fe165590-5144-4f1e-bece-4be174404c79';

-- Check your punches in 7shifts.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Check 7shifts regularly","es":"Revisa 7shifts seguido"},"sub":{"en":"Your punches show up in real time","es":"Tus registros aparecen en tiempo real"}},{"title":{"en":"Something off? Tell your manager","es":"¿Algo no cuadra? Avísale a tu gerente"},"sub":{"en":"Right away","es":"De inmediato"}},{"title":{"en":"Bring the specifics","es":"Trae los detalles"},"sub":{"en":"Dates, hours, and details","es":"Fechas, horas y detalles específicos"}}],"note":{"en":"Adjustments can't be made from memory alone.","es":"Los ajustes no se pueden hacer solo de memoria."},"why":{"en":"A wrong punch is easiest to fix while it's fresh — and you'll know your pay is right before payday.","es":"Un registro equivocado es más fácil de corregir cuando está reciente — y sabrás que tu pago está bien antes del día de pago."},"example":{"en":"7shifts shows you clocked out at 9:00, but you closed at 10:15? Tell your manager with the date and both times.","es":"¿7shifts dice que marcaste salida a las 9:00 pero cerraste a las 10:15? Avísale a tu gerente con la fecha y ambas horas."}}$IG$::jsonb, updated_at = now() where id = '5aca5e3b-b217-4f77-988b-0a1e47bab1b5';

-- Never clock in for someone else.
