-- ════════ Meals & Perks ════════

-- Working a scheduled shift? You get a meal discount.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Your meal discount","es":"Tu descuento de comida"},"icon":"bowl","lines":[{"en":"Eat it only on your designated break","es":"Cómela solo en tu descanso designado"},{"en":"Only once you're clocked out","es":"Solo con tu salida ya marcada"}]},"right":{"title":{"en":"Managers","es":"Gerentes"},"icon":"gift","lines":[{"en":"One free shift meal per shift","es":"Una comida de turno gratis por turno"},{"en":"Up to $15","es":"Hasta $15"},{"en":"No more than two free meals a day","es":"No más de dos comidas gratis al día"}]},"why":{"en":"We want you to know the menu and enjoy the food you help serve.","es":"Queremos que conozcas el menú y disfrutes la comida que ayudas a servir."},"example":{"en":"A manager working a double gets up to two free meals that day — one per shift, each up to $15.","es":"Un gerente que trabaja doble turno recibe hasta dos comidas gratis ese día — una por turno, cada una de hasta $15."}}$IG$::jsonb, updated_at = now() where id = '7af67978-c484-4994-b2ce-ee45af82f6d1';

-- Ring every meal into the POS before you take a bite.
