-- Eating here off the clock? You may get a discount.
update handbook_cards set infographic = $IG${"type":"stat","value":"4","unit":{"en":"guests","es":"invitados"},"label":{"en":"The most it can cover","es":"Lo máximo que puede cubrir"},"sub":{"en":"Alcohol isn't included unless management authorizes it. The discount may be suspended on high-volume days.","es":"El alcohol no está incluido a menos que la gerencia lo autorice. El descuento puede suspenderse en días de alto volumen."},"icon":"users","footer":{"tone":"info","text":{"en":"Ask your manager for the specifics at your location.","es":"Pregúntale a tu gerente los detalles específicos de tu ubicación."}},"why":{"en":"It's a thank-you for being part of the team — but on our busiest days, the floor has to put guests first.","es":"Es un agradecimiento por ser parte del equipo — pero en nuestros días más ocupados, el piso tiene que darles prioridad a los clientes."},"example":{"en":"Bringing three friends to dinner on your day off? Heads-up: on a packed Saturday, the discount may be suspended.","es":"¿Vienes a cenar con tres amigos en tu día libre? Ojo: en un sábado lleno, el descuento puede estar suspendido."}}$IG$::jsonb, updated_at = now() where id = '25bef01d-4177-4e7c-af93-d6f0fe2f01c4';

-- PTO is for salaried managers — hourly staff aren’t eligible right now.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Years 1–2","es":"Años 1–2"},"sub":{"en":"5 days a year","es":"5 días al año"}},{"title":{"en":"Years 3–4","es":"Años 3–4"},"sub":{"en":"10 days a year","es":"10 días al año"}},{"title":{"en":"Year 5 and up","es":"Año 5 en adelante"},"sub":{"en":"14 days a year","es":"14 días al año"}}],"note":{"en":"For salaried managers and assistant managers. Resets on your work anniversary; unused days don't carry over. GM or ownership approves every request — you can't approve your own. Cashing out is an owner-approved exception only: never automatic, never guaranteed, always in writing.","es":"Para gerentes y sub-gerentes asalariados. Se reinicia en tu aniversario de empleo; los días no usados no se acumulan. El Gerente General o los propietarios aprueban cada solicitud — no puedes aprobar la tuya. Cobrar el PTO es una excepción aprobada solo por los propietarios: nunca automática, nunca garantizada, siempre por escrito."},"noteTone":"info","why":{"en":"Our salaried managers carry a lot — PTO that grows with tenure gives them real time to recharge.","es":"Nuestros gerentes asalariados cargan con mucho — un PTO que crece con la antigüedad les da tiempo real para recargar energía."},"example":{"en":"Hired in June 2024? Your June 2026 anniversary starts year 3: 10 days — and unused year-2 days don't carry over.","es":"¿Te contrataron en junio de 2024? Tu aniversario de junio de 2026 inicia tu año 3: 10 días — y los días no usados del año 2 no se acumulan."}}$IG$::jsonb, updated_at = now() where id = '6465aea5-3a5c-45f9-9151-350fc4460701';

-- Full-time? You may qualify for health insurance after 90 days.
update handbook_cards set infographic = $IG${"type":"stat","value":"25%","label":{"en":"What the Company currently contributes toward coverage","es":"Lo que la Compañía contribuye actualmente hacia la cobertura"},"sub":{"en":"Employer-supported coverage for eligible full-time employees.","es":"Cobertura con apoyo del empleador para empleados elegibles de tiempo completo."},"icon":"heart","footer":{"tone":"info","text":{"en":"Enrollment happens during annual open enrollment in October.","es":"La inscripción se realiza durante la inscripción abierta anual en octubre."}},"why":{"en":"Taking care of the team means helping with what matters outside of work, too.","es":"Cuidar al equipo también significa ayudar con lo que importa fuera del trabajo."},"example":{"en":"Started full-time on July 1? You pass 90 days at the end of September — right before October open enrollment.","es":"¿Empezaste de tiempo completo el 1 de julio? Cumples 90 días a finales de septiembre — justo antes de la inscripción abierta de octubre."}}$IG$::jsonb, updated_at = now() where id = '885a177e-ae08-4516-9b1c-4b4a83e7ada0';

-- Eligible? You may join our 401(k) retirement plan.
update handbook_cards set infographic = $IG${"type":"icon","icon":"growth","phrase":{"en":"Save for retirement — with an employer match","es":"Ahorra para tu retiro — con una contribución del empleador"},"sub":{"en":"The match goes up to a defined percentage. Joining is voluntary — but strongly encouraged.","es":"La contribución equivalente llega hasta un porcentaje definido. Participar es voluntario — pero te lo recomendamos mucho."},"note":{"en":"Enrollment details are provided separately.","es":"Los detalles de inscripción se dan por separado."},"noteTone":"info","why":{"en":"We want this job to help build your future, not just cover this week's bills.","es":"Queremos que este trabajo te ayude a construir tu futuro, no solo a cubrir los gastos de la semana."}}$IG$::jsonb, updated_at = now() where id = 'a7f63fa6-a7ab-4476-aae8-71ba005795e8';

-- Full-time BOH hourly? Meet all 3 to qualify for the quarterly bonus.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"No unexcused absences or call-outs","es":"Sin ausencias injustificadas ni reportes de ausencia"},{"en":"No active disciplinary documentation","es":"Sin documentación disciplinaria activa"},{"en":"A positive performance evaluation","es":"Una evaluación de desempeño positiva"}],"badge":{"en":"All 3 required","es":"Los 3 son necesarios"},"note":{"en":"You need all three during that quarter. Bonus amounts are set by location and aren't guaranteed.","es":"Necesitas los tres durante ese trimestre. Los montos del bono los determina cada ubicación y no están garantizados."},"noteTone":"info","why":{"en":"A kitchen runs on people who show up and do the work well — this bonus recognizes exactly that.","es":"Una cocina funciona gracias a quienes llegan y hacen bien su trabajo — este bono reconoce justo eso."},"example":{"en":"One unexcused absence in May means you don't qualify for that quarter's bonus — even with a great evaluation.","es":"Una ausencia injustificada en mayo significa que no calificas al bono de ese trimestre — aunque tengas una gran evaluación."}}$IG$::jsonb, updated_at = now() where id = 'a2f472eb-7000-4644-aecb-20a9bd5d0d5c';

-- In good standing? You may be eligible for an end-of-year bonus.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"End-of-year bonus","es":"Bono de fin de año"},"icon":"gift","lines":[{"en":"Based on tenure and performance","es":"Se basa en tu antigüedad y desempeño"},{"en":"Not guaranteed","es":"No está garantizado"}]},"right":{"title":{"en":"Holiday recognition event","es":"Evento de reconocimiento por las fiestas"},"icon":"star","lines":[{"en":"Every year","es":"Cada año"},{"en":"All staff are part of it","es":"Todo el personal forma parte"}]},"note":{"en":"Any benefit may change at any time — you'll be told as changes happen.","es":"Cualquier beneficio puede cambiar en cualquier momento — se te avisará conforme ocurran los cambios."},"noteTone":"info","why":{"en":"We want to recognize the people who stay and do great work — and celebrate the whole team together.","es":"Queremos reconocer a quienes se quedan y hacen un gran trabajo — y celebrar juntos como equipo."}}$IG$::jsonb, updated_at = now() where id = 'ca905352-bd08-4a10-bee6-bfef618c3f89';


-- ════════ Pay & Payroll ════════

-- Payday is the 5th and the 20th of every month.
update handbook_cards set infographic = $IG${"type":"periods","periods":[{"range":{"en":"1st–15th","es":"Del 1 al 15"},"pay":{"en":"20th","es":"El 20"}},{"range":{"en":"16th–end of month","es":"Del 16 a fin de mes"},"pay":{"en":"5th of next month","es":"El 5 del mes siguiente"}}],"note":{"en":"Payday on a weekend or bank holiday? You're paid on the nearest business day before it.","es":"¿El día de pago cae en fin de semana o feriado bancario? Te pagan el día hábil anterior más cercano."},"why":{"en":"Two fixed paydays a month means you can plan your bills around them.","es":"Dos días de pago fijos al mes te permiten planear tus cuentas alrededor de ellos."},"example":{"en":"Worked the 1st–15th? That's paid on the 20th — and if the 20th is a Sunday, you're paid Friday the 18th.","es":"¿Trabajaste del 1 al 15? Se paga el 20 — y si el 20 cae en domingo, te pagan el viernes 18."}}$IG$::jsonb, updated_at = now() where id = 'd351141e-d301-4469-9df7-d500faafbac6';

-- Training pays $8.00 an hour — no matter your position.
update handbook_cards set infographic = $IG${"type":"stat","value":"$8","unit":{"en":"/hr","es":"/hora"},"label":{"en":"during your designated training period","es":"durante tu período de entrenamiento designado"},"sub":{"en":"Your regular rate starts once your manager confirms your training is complete.","es":"Tu tarifa regular empieza cuando tu gerente confirma que tu entrenamiento está completo."},"icon":"book","why":{"en":"During training you're learning the role, not running it yet — so everyone starts at the same rate.","es":"Durante el entrenamiento estás aprendiendo el puesto, todavía no lo manejas — por eso todos empiezan con la misma tarifa."},"example":{"en":"Server, cook, or host — during training, everyone earns $8 an hour until their manager confirms training is complete.","es":"Mesero, cocinero o host — durante el entrenamiento, todos ganan $8 por hora hasta que su gerente confirma que el entrenamiento está completo."}}$IG$::jsonb, updated_at = now() where id = '80f6d47b-c4ab-4e71-a675-ed6768eb639d';

-- Your pay stubs and W-2 are in the Paychex app.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Download it and keep your account active — strongly encouraged","es":"Descárgala y mantén tu cuenta activa — te lo recomendamos mucho"},{"en":"Manage your direct deposit","es":"Maneja tu depósito directo"},{"en":"Update your tax withholding","es":"Actualiza tus retenciones de impuestos"}],"note":{"en":"Keeping your personal and banking info current in Paychex is your responsibility.","es":"Mantener tu información personal y bancaria al día en Paychex es tu responsabilidad."},"why":{"en":"Your deposit and your tax forms go wherever Paychex says — current info means they reach you.","es":"Tu depósito y tus documentos de impuestos van a donde Paychex indique — con tu información al día, te llegan a ti."},"example":{"en":"Filing your taxes? Download your W-2 straight from the Paychex app.","es":"¿Vas a declarar impuestos? Descarga tu W-2 directamente de la app de Paychex."}}$IG$::jsonb, updated_at = now() where id = '479d762f-18c4-47eb-8b13-e7f78f7d31cb';

-- Direct deposit is required for everyone.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Set it up in Paychex","es":"Configúralo en Paychex"},"sub":{"en":"During onboarding","es":"Durante tu incorporación"}},{"title":{"en":"Bank info changes? Update it","es":"¿Cambió tu información bancaria? Actualízala"},"sub":{"en":"In the Paychex app, or tell the office manager","es":"En la app de Paychex, o avísale al gerente de oficina"}}],"note":{"en":"Make the change before the payroll cutoff for the upcoming pay period.","es":"Haz el cambio antes de la fecha límite de nómina del próximo período de pago."},"why":{"en":"Direct deposit gets your pay to you on payday — nothing to pick up, nothing to lose.","es":"El depósito directo te hace llegar tu pago el día de pago — nada que recoger, nada que perder."},"example":{"en":"Opening a new bank account? Update Paychex before the payroll cutoff so the next deposit goes to the right place.","es":"¿Abriste una cuenta bancaria nueva? Actualiza Paychex antes de la fecha límite de nómina para que el siguiente depósito llegue al lugar correcto."}}$IG$::jsonb, updated_at = now() where id = 'c0841e12-754a-414a-a9d3-453d7e12f18d';

-- Over 40 hours in a workweek? That’s overtime at 1.5×.
update handbook_cards set infographic = $IG${"type":"stat","value":"1.5×","label":{"en":"your regular rate, per overtime hour","es":"tu tarifa regular, por cada hora extra"},"sub":{"en":"For non-exempt hourly employees, on every hour over 40. Overtime is calculated weekly — and must be pre-approved by management.","es":"Para empleados por hora no exentos, por cada hora arriba de 40. Las horas extra se calculan por semana — y deben ser pre-aprobadas por la gerencia."},"icon":"clock","footer":{"tone":"warn","text":{"en":"Unauthorized overtime is handled as a conduct issue — but you'll always be paid for every hour you work.","es":"Las horas extra no autorizadas se tratan como un problema de conducta — pero siempre se te paga por cada hora trabajada."}},"why":{"en":"Overtime costs 50% more per hour, so it has to be planned ahead — not discovered on payday.","es":"Las horas extra cuestan 50% más por hora, así que hay que planearlas — no descubrirlas el día de pago."},"example":{"en":"38 hours one week, 44 the next? Only the 4 hours past 40 in the second week are overtime.","es":"¿38 horas una semana y 44 la siguiente? Solo las 4 horas arriba de 40 de la segunda semana son horas extra."}}$IG$::jsonb, updated_at = now() where id = 'fdb91795-86df-42e3-bd85-3b10aff6a730';

-- Enter your tips on the 7Punches iPad before you leave.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Clock out on the 7Punches iPad","es":"Marca salida en el iPad de 7Punches"},"sub":{"en":"At the end of every shift","es":"Al final de cada turno"}},{"title":{"en":"Enter your tips","es":"Ingresa tus propinas"},"sub":{"en":"Right then — before you leave","es":"En ese momento — antes de irte"}}],"note":{"en":"Tipped positions are paid a tipped hourly wage under Louisiana and federal law. Tip pool and tip-out arrangements vary by location — they're in your position-specific training materials.","es":"Las posiciones con propinas reciben un salario por hora con propinas de acuerdo con la ley de Louisiana y la ley federal. Los arreglos de propina compartida y distribución de propinas varían según la ubicación — están en los materiales de capacitación de tu posición."},"why":{"en":"Your tips are part of your pay — recording them every shift keeps your pay stub and tax records accurate.","es":"Tus propinas son parte de tu pago — registrarlas en cada turno mantiene correctos tu recibo de pago y tus registros de impuestos."}}$IG$::jsonb, updated_at = now() where id = '5790bc9a-49e2-4cba-98c0-2da018d65515';

-- Think your pay is wrong? Bring dates, hours, and supporting data.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Check your hours in 7shifts regularly — punches show in real time","es":"Revisa tus horas seguido en 7shifts — muestra tus registros en tiempo real"},{"en":"Raise any error with your manager promptly","es":"Reporta cualquier error a tu gerente de inmediato"}],"dont":[{"en":"Let an error sit","es":"Dejar pasar un error"},{"en":"Rely on memory alone","es":"Confiar solo en la memoria"}],"note":{"en":"Adjustments can't be made based on memory alone.","es":"Los ajustes no se pueden hacer basándose solo en la memoria."},"why":{"en":"Every correction has to be checked against the records — specifics are what make that possible.","es":"Cada corrección se tiene que verificar con los registros — los detalles específicos son lo que lo hace posible."},"example":{"en":"“Tuesday the 14th, I closed at 10:30 but my punch shows 9:00” can be checked. “I think I was short last week” can't.","es":"“El martes 14 cerré a las 10:30 pero mi registro dice 9:00” se puede verificar. “Creo que me faltó algo la semana pasada” no."}}$IG$::jsonb, updated_at = now() where id = 'a9000b1e-fbc2-4636-8996-bbd9c6d3297c';

-- Never pad your time or have someone punch for you.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Record only the hours you actually work","es":"Registra solo las horas que realmente trabajas"}],"dont":[{"en":"Deliberately manipulate time records to inflate pay","es":"Manipular a propósito los registros de tiempo para inflar tu pago"},{"en":"Clock in early or out late without authorization","es":"Marcar entrada temprano o salida tarde sin autorización"},{"en":"Have another employee punch for you","es":"Pedirle a otro empleado que marque por ti"}],"note":{"en":"All of these are time fraud. Time fraud results in immediate termination.","es":"Todo esto es fraude de tiempo. El fraude de tiempo resulta en terminación inmediata."},"noteTone":"warn","why":{"en":"Every punch is a record of real work — payroll and the team's trust both depend on it being true.","es":"Cada registro es constancia de trabajo real — la nómina y la confianza del equipo dependen de que sea verdad."}}$IG$::jsonb, updated_at = now() where id = 'e822d1a8-8a64-455e-96d7-7e5a950127a7';

-- A valid wage garnishment will show on your pay stub.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"A valid order arrives","es":"Llega una orden válida"},"sub":{"en":"The Company receives a legally valid garnishment order","es":"La Compañía recibe una orden de embargo legalmente válida"}},{"title":{"en":"The law requires us to comply","es":"La ley nos obliga a cumplirla"}},{"title":{"en":"It shows on your pay stub","es":"Aparece en tu recibo de pago"}}],"note":{"en":"Questions about a specific garnishment? Contact the issuing agency directly.","es":"¿Preguntas sobre un embargo específico? Contacta directamente a la agencia emisora."},"why":{"en":"A garnishment comes from outside the company — when the order is legally valid, following it isn't optional for us.","es":"Un embargo viene de fuera de la compañía — cuando la orden es legalmente válida, cumplirla no es opcional para nosotros."}}$IG$::jsonb, updated_at = now() where id = '00fd595d-32b5-4dfb-9b1f-f2b44a527f36';


-- ════════ Dress Code & Appearance ════════

-- Wear a clean, unwrinkled uniform in good condition every shift.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"The Company","es":"La Compañía"},"icon":"gift","lines":[{"en":"Provides your first uniforms","es":"Te da tus primeros uniformes"},{"en":"Details what to wear in your position training materials","es":"Detalla qué usar en tus materiales de capacitación de posición"}]},"right":{"title":{"en":"You","es":"Tú"},"icon":"shirt","lines":[{"en":"Keep them clean, unwrinkled, and in good condition","es":"Mantenerlos limpios, sin arrugas y en buen estado"},{"en":"Wear what your position and location call for","es":"Usar lo que corresponde a tu posición y ubicación"}]},"note":{"en":"Show up out of uniform and you may be sent home to fix it — that time isn't paid.","es":"Si llegas sin uniforme, te pueden enviar a casa a corregirlo — y ese tiempo no se paga."},"noteTone":"warn","why":{"en":"Guests notice the details before they taste the food — a sharp uniform tells them we care.","es":"Los clientes notan los detalles antes de probar la comida — un uniforme impecable les dice que nos importa."},"example":{"en":"Spilled broth on your shirt Friday night? Wash it before Saturday's shift — upkeep is on you.","es":"¿Se te cayó caldo en la camisa el viernes en la noche? Lávala antes de tu turno del sábado — mantenerla te toca a ti."}}$IG$::jsonb, updated_at = now() where id = 'e2912016-e9b4-4d9a-9dde-9ae3dce0fa36';

-- Keep your hair off your face and shoulders during service.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Everyone","es":"Todos"},"icon":"users","lines":[{"en":"Hair clean and controlled","es":"Cabello limpio y controlado"}]},"right":{"title":{"en":"BOH & anyone handling food","es":"BOH y quien maneje alimentos"},"icon":"bowl","lines":[{"en":"Must wear a hair restraint","es":"Deben usar redecilla o sujetador de cabello"}]},"why":{"en":"A stray hair can ruin a guest's meal — keeping it controlled is about food safety, not just looks.","es":"Un cabello suelto puede arruinar la comida de un cliente — mantenerlo controlado es cuestión de seguridad alimentaria, no solo de imagen."},"example":{"en":"Making rolls at the sushi bar in front of guests? You're handling food — hair restraint on.","es":"¿Preparas rollos en la barra de sushi frente a los clientes? Estás manejando alimentos — usa tu sujetador de cabello."}}$IG$::jsonb, updated_at = now() where id = '0fb89d1b-7e47-4cd0-924c-ccf96a442a38';

-- Show up fresh: short clean nails, deodorant, little or no fragrance.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Keep hands and nails clean, nails short","es":"Manos y uñas limpias, uñas cortas"},{"en":"Wear deodorant — it's a physical job in a warm space","es":"Usa desodorante — es un trabajo físico en un ambiente caluroso"},{"en":"Keep cologne or perfume minimal, or skip it","es":"Usa poca colonia o perfume, o mejor nada"}],"dont":[{"en":"Chipped or overly decorative polish","es":"Esmalte descascarado o excesivamente decorativo"},{"en":"Strong scents — they bother guests and coworkers","es":"Fragancias fuertes — molestan a clientes y compañeros"}],"why":{"en":"You work up close with guests, teammates, and food — how you show up is part of the experience.","es":"Trabajas de cerca con clientes, compañeros y comida — cómo te presentas es parte de la experiencia."},"example":{"en":"Coming straight from the gym? Deodorant, yes — a heavy spray of cologne, no.","es":"¿Vienes directo del gimnasio? Desodorante, sí — mucha colonia, no."}}$IG$::jsonb, updated_at = now() where id = '0c2cc5c3-dca3-4bdb-b4d1-efa4900bb485';

-- Wash your hands often — including after touching your phone.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"When you arrive","es":"Al llegar"},{"en":"After the restroom","es":"Después de usar el baño"},{"en":"After handling raw proteins","es":"Después de manejar proteínas crudas"},{"en":"After touching your face or phone","es":"Después de tocarte la cara o el teléfono"}],"badge":{"en":"Every time","es":"Cada vez"},"note":{"en":"Plus after anything else that could contaminate food or surfaces.","es":"Y después de cualquier otra cosa que pueda contaminar alimentos o superficies."},"noteTone":"info","why":{"en":"Clean hands are the simplest way to keep guests and teammates from getting sick.","es":"Las manos limpias son la forma más sencilla de evitar que clientes y compañeros se enfermen."},"example":{"en":"Checked a text on your break? Wash your hands before you go back to the line.","es":"¿Revisaste un mensaje en tu descanso? Lávate las manos antes de volver a la línea."}}$IG$::jsonb, updated_at = now() where id = '35524d5b-7be1-4192-be55-c778a349a8e8';

-- Glove use depends on which restaurant you work at.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Ramen restaurants","es":"Restaurantes de ramen"},"icon":"bowl","lines":[{"en":"Gloves encouraged during food prep","es":"Se fomenta el uso de guantes durante la preparación"}]},"right":{"title":{"en":"Sushi restaurants","es":"Restaurantes de sushi"},"icon":"hand","lines":[{"en":"Bare-hand craftsmanship is standard","es":"La elaboración a mano es el estándar"},{"en":"Frequent handwashing strictly required throughout service","es":"Lavado frecuente de manos estrictamente requerido durante todo el servicio"}]},"note":{"en":"Your training materials cover the specifics for your position.","es":"Tus materiales de capacitación tienen los detalles para tu posición."},"noteTone":"info","why":{"en":"Each restaurant follows its own craft — and at the sushi bar, that craft is done by hand.","es":"Cada restaurante sigue su propio oficio — y en la barra de sushi, ese oficio se hace a mano."},"example":{"en":"Prepping toppings at Boru? Gloves are encouraged. Shaping nigiri at Ichiban? Bare hands, washed often all service.","es":"¿Preparas ingredientes en Boru? Se fomentan los guantes. ¿Formas nigiri en Ichiban? A mano, con lavado frecuente todo el servicio."}}$IG$::jsonb, updated_at = now() where id = '1d7c53f0-bd88-4725-b334-e8000b7e77c7';

-- Tattoos are OK if they’re appropriate for a family dining environment.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Tattoos","es":"Tatuajes"},"icon":"hand","lines":[{"en":"Management may ask you to cover certain ones during service","es":"La gerencia puede pedirte que cubras algunos durante el servicio"}]},"right":{"title":{"en":"Piercings","es":"Piercings"},"icon":"star","lines":[{"en":"Minimal and professional","es":"Mínimos y profesionales"},{"en":"Doesn't fit presentation standards? A clear or neutral retainer works","es":"¿No va con los estándares de presentación? Un retenedor transparente o neutro funciona"}]},"note":{"en":"Asked to cover up? Just do it — it's not a floor debate. Decisions are applied consistently and handled privately.","es":"¿Te piden cubrirte? Hazlo sin discutir — no es un debate en el piso. Las decisiones se aplican de forma consistente y se manejan en privado."},"noteTone":"info","why":{"en":"We serve families every day, so how we look should feel welcoming at every table.","es":"Atendemos a familias todos los días, así que nuestra imagen debe sentirse acogedora en cada mesa."},"example":{"en":"Asked to cover a tattoo right before dinner service? Cover it first — any questions come later, in private.","es":"¿Te piden cubrir un tatuaje justo antes del servicio de la cena? Cúbrelo primero — cualquier pregunta va después, en privado."}}$IG$::jsonb, updated_at = now() where id = 'beba75e3-d33e-467b-83ac-da56026a6f8f';

-- Keep personal items — even your water bottle — in employee areas.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Keep personal items in employee areas","es":"Guarda tus cosas personales en el área de empleados"},{"en":"Same for personal food and drinks — water bottle included","es":"Lo mismo con tu comida y bebidas personales — botella de agua incluida"}],"dont":[{"en":"Service areas or expo","es":"Áreas de servicio o la estación de expedición"},{"en":"Behind the bar or on the line","es":"Detrás del bar o en la línea"},{"en":"Kitchen workspaces or food prep surfaces","es":"Espacios de trabajo de la cocina o superficies de preparación de alimentos"}],"note":{"en":"This is a health department requirement — personal items in food areas are a health code violation.","es":"Es un requisito del departamento de salud — los artículos personales en áreas de alimentos son una violación del código de salud."},"noteTone":"warn","why":{"en":"What sits near the food can end up in the food — that's why the health department draws a hard line.","es":"Lo que está cerca de la comida puede terminar en la comida — por eso el departamento de salud es tan estricto."},"example":{"en":"Thirsty on the line? Step back to the employee area for a drink — your bottle stays there.","es":"¿Tienes sed en la línea? Ve al área de empleados a tomar agua — tu botella se queda ahí."}}$IG$::jsonb, updated_at = now() where id = 'c1673e87-57cb-4612-84fa-8a425f906313';


-- ════════ Phones, Breaks & Daily Conduct ════════

-- Handle disagreements privately after your shift — not on the floor.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"During service","es":"Durante el servicio"},"icon":"users","lines":[{"en":"Follow your manager's direction","es":"Sigue las instrucciones de la gerencia"},{"en":"No arguing","es":"Sin discutir"}]},"right":{"title":{"en":"After your shift","es":"Después de tu turno"},"icon":"chat","lines":[{"en":"Disagree with a decision? Raise it privately","es":"¿No estás de acuerdo con una decisión? Abórdala en privado"},{"en":"Through the right channel, at the right time","es":"Por el canal correcto, en el momento adecuado"}]},"note":{"en":"Respectful, clear communication with teammates and guests is the baseline — not a perk.","es":"La comunicación respetuosa y clara con compañeros y clientes es lo mínimo esperado — no un extra."},"noteTone":"info","why":{"en":"Guests can feel tension on the floor — taking it offline keeps service smooth and the conversation calmer.","es":"Los clientes perciben la tensión en el piso — hablarlo fuera del servicio mantiene todo fluyendo y la conversación más tranquila."},"example":{"en":"Moved to a different section mid-rush? Go where you're sent, then talk it through with your manager after your shift.","es":"¿Te cambiaron de sección en plena hora pico? Ve a donde te mandan y luego platícalo con tu gerente después de tu turno."}}$IG$::jsonb, updated_at = now() where id = 'c48b57fe-aecf-426f-a757-5522e902f1ad';

-- Slow moment? Clean, stock, prep, or help a teammate.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Anticipate what needs to be done","es":"Anticipa lo que hay que hacer"},{"en":"Do it without being told","es":"Hazlo sin que te lo digan"},{"en":"If it needs to happen and you can do it, do it","es":"Si algo necesita hacerse y tú puedes hacerlo, hazlo"}],"dont":[{"en":"Say “That's not my job” — that phrase doesn't exist here","es":"Decir “Eso no es mi trabajo” — esa frase no existe aquí"}],"why":{"en":"A slow few minutes is the best time to set up the next rush — and the whole team feels the difference.","es":"Unos minutos tranquilos son el mejor momento para prepararse para la siguiente hora pico — y todo el equipo nota la diferencia."},"example":{"en":"Dining room quiet at 3:00? Restock to-go supplies, wipe down menus, or ask the kitchen if they need a hand.","es":"¿El comedor está tranquilo a las 3:00? Surte los insumos para llevar, limpia los menús o pregúntale a la cocina si necesita ayuda."}}$IG$::jsonb, updated_at = now() where id = '7eb16e85-0fcc-4776-928b-4ede51b52dbb';

-- Hold the standard whether anyone’s watching or not.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Security cameras","es":"Cámaras de seguridad"},"icon":"camera","lines":[{"en":"In use in work areas at every restaurant","es":"En uso en las áreas de trabajo de todos los restaurantes"},{"en":"You should have no expectation of privacy there","es":"Ahí no debes tener expectativa de privacidad"},{"en":"Ownership watches footage","es":"Los propietarios revisan las cámaras"}]},"right":{"title":{"en":"Reviewed regularly","es":"Se revisan regularmente"},"icon":"clipboard","lines":[{"en":"POS activity","es":"Actividad del POS"},{"en":"Clock punches","es":"Registros de entrada y salida"},{"en":"Transaction data","es":"Datos de transacciones"}]},"note":{"en":"Only stepping it up when a manager is in your section doesn't meet our standard. Your patterns show up over time — monitoring is there to protect everyone, employees and guests included.","es":"Esforzarte solo cuando un gerente está en tu sección no cumple con nuestro estándar. Tus patrones se notan con el tiempo — el monitoreo existe para proteger a todos, empleados y clientes incluidos."},"noteTone":"info","why":{"en":"Guests don't know who's watching — they just know whether their night was great.","es":"Los clientes no saben quién está observando — solo saben si su noche fue excelente."},"example":{"en":"Manager steps into the office for 20 minutes? Your section runs exactly the way it did while they were on the floor.","es":"¿El gerente entra a la oficina 20 minutos? Tu sección funciona exactamente igual que cuando estaba en el piso."}}$IG$::jsonb, updated_at = now() where id = 'e10f0227-4af8-49e0-9e55-819852b65844';

-- Keep your phone put away and out of sight on shift.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Use it only on your clocked-out break","es":"Úsalo solo en tu descanso con salida marcada"},{"en":"A quick glance for a genuine emergency is understandable","es":"Una mirada rápida por una emergencia genuina es entendible"}],"dont":[{"en":"On the floor, in service areas, or any guest-facing space","es":"En el piso, en áreas de servicio o en cualquier espacio frente a los clientes"},{"en":"Between tables, at expo, or in the restroom during service","es":"Entre mesas, en la estación de expedición o en el baño durante el servicio"},{"en":"Scrolling, texting, or social media during service","es":"Navegar, mandar mensajes o usar redes sociales durante el servicio"}],"note":{"en":"Managers may use phones for work communication only.","es":"Los gerentes pueden usar el teléfono solo para comunicación de trabajo."},"noteTone":"info","why":{"en":"A phone in hand pulls your attention from guests and your team — and guests notice right away.","es":"Un teléfono en la mano te quita atención de los clientes y de tu equipo — y los clientes lo notan de inmediato."},"example":{"en":"Want to check a text between tickets at expo? Wait for your clocked-out break.","es":"¿Quieres revisar un mensaje entre comandas en la estación de expedición? Espera a tu descanso con salida marcada."}}$IG$::jsonb, updated_at = now() where id = '0772784b-8509-45d3-80c8-1e2aeae1ca69';

-- Music off, earbuds out — the moment a guest arrives or service begins.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Guest-facing areas","es":"Áreas frente a los clientes"},"icon":"users","lines":[{"en":"No earbuds or headphones","es":"Nada de audífonos ni auriculares"},{"en":"Includes Boru Ramen's open kitchen","es":"Incluye la cocina abierta de Boru Ramen"},{"en":"Includes Ichiban's sushi bar","es":"Incluye la barra de sushi de Ichiban"}]},"right":{"title":{"en":"Dead hours","es":"Horas muertas"},"icon":"clock","lines":[{"en":"The only exception","es":"La única excepción"},{"en":"Just one earbud — never both","es":"Solo un audífono — nunca ambos"}]},"why":{"en":"During service, communication is essential — audio devices get in the way.","es":"Durante el servicio la comunicación es esencial — los dispositivos de audio la obstaculizan."},"example":{"en":"First guest walks in while you're finishing side work with one earbud? Music off, earbud out — right then.","es":"¿Entra el primer cliente mientras terminas tu trabajo de apoyo con un audífono? Música apagada y audífono fuera — en ese momento."}}$IG$::jsonb, updated_at = now() where id = '03d984ce-cdfa-49b9-9e36-ca7bb4718667';

-- Dead hours only: one earbud is OK — never both.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"One earbud, low volume — you must still hear your team","es":"Un audífono, volumen bajo — siempre debes poder escuchar a tu equipo"},{"en":"Personal speakers at low volume in non-guest areas, same windows only","es":"Bocinas personales a volumen bajo en áreas fuera de la vista del cliente, solo en esas mismas ventanas"},{"en":"Stick to non-guest areas pre- and post-shift","es":"Antes y después del turno, solo en áreas fuera de la vista del cliente"}],"dont":[{"en":"Both earbuds — ever","es":"Ambos audífonos — nunca"},{"en":"Keep music or an earbud in once a guest arrives","es":"Seguir con música o audífono cuando llega un cliente"}],"note":{"en":"Dead hours: before open, after close, or a genuine zero-guest lull mid-shift.","es":"Horas muertas: antes de abrir, después de cerrar o un periodo genuino sin clientes a mitad de turno."},"noteTone":"info","why":{"en":"A little music can make side work go by — as long as you can still hear the team.","es":"Un poco de música puede hacer más llevadero el trabajo de apoyo — siempre que puedas escuchar al equipo."},"example":{"en":"Prepping in the back before open? One earbud, low volume — and out the second a guest walks in.","es":"¿Preparando en la parte de atrás antes de abrir? Un audífono, volumen bajo — y fuera en cuanto entra un cliente."}}$IG$::jsonb, updated_at = now() where id = '16b32745-70c0-4cc9-b721-cc86c4142f37';

-- No scheduled breaks during peak: 11:30am–1:30pm and 5:30pm–8:30pm.
update handbook_cards set infographic = $IG${"type":"day","from":"10:00","to":"22:00","blocks":[{"start":"11:30","end":"13:30"},{"start":"17:30","end":"20:30"}],"blockLabel":{"en":"Peak — no scheduled breaks","es":"Hora pico — sin descansos programados"},"openLabel":{"en":"Outside peak hours, breaks happen at manager-approved times.","es":"Fuera de las horas pico, los descansos son en horarios aprobados por el gerente."},"note":{"en":"Urgent restroom need or genuine emergency? Notify the manager on duty. Five minutes is expected; ten is the absolute maximum.","es":"¿Necesidad urgente de ir al baño o una emergencia genuina? Avísale al gerente en turno. Se esperan cinco minutos; diez es el máximo absoluto."},"noteTone":"info","why":{"en":"Peak hours are when guests need all of us — one missing person is felt across the whole floor.","es":"Las horas pico son cuando los clientes nos necesitan a todos — una persona menos se siente en todo el piso."},"example":{"en":"Working 4 to 10? Any scheduled break falls before 5:30 or after 8:30, at a time your manager approves.","es":"¿Trabajas de 4 a 10? Cualquier descanso programado es antes de las 5:30 o después de las 8:30, a la hora que apruebe tu gerente."}}$IG$::jsonb, updated_at = now() where id = 'd2137f4f-0f78-45eb-b5a4-6b2c9ee6dc2d';

-- Take breaks clocked out and out of guests’ view.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Clock out before you leave your station","es":"Marca salida antes de dejar tu estación"},{"en":"Eat in the designated area","es":"Come en el área designada"},{"en":"Use your phone, decompress","es":"Usa tu teléfono, relájate"}],"dont":[{"en":"Long chats with coworkers still on the clock","es":"Pláticas largas con compañeros que están trabajando"},{"en":"Distract anyone mid-service","es":"Distraer a alguien a mitad del servicio"}],"note":{"en":"Staying clocked in on a break is a timekeeping violation.","es":"Quedarte con el reloj marcado en un descanso es una violación de control de tiempo."},"noteTone":"warn","why":{"en":"A real break means real rest — and accurate punches keep everyone's pay right.","es":"Un descanso de verdad significa descansar de verdad — y los registros correctos mantienen bien el pago de todos."},"example":{"en":"Break at 3:15? Clock out first, then eat in the designated area — not at a table guests can see.","es":"¿Descanso a las 3:15? Marca salida primero y luego come en el área designada — no en una mesa a la vista de los clientes."}}$IG$::jsonb, updated_at = now() where id = 'ac5096a2-03dc-43a1-bbd5-edffac06ff2c';

-- Got an issue? Bring it straight to management.
update handbook_cards set infographic = $IG${"type":"icon","icon":"chat","phrase":{"en":"A coworker, a policy, or a situation","es":"Un compañero, una política o una situación"},"sub":{"en":"Whatever kind of issue it is, the path is the same.","es":"Sea el tipo de problema que sea, el camino es el mismo."},"why":{"en":"Management can only fix what it knows about — going straight there keeps small issues from growing.","es":"La gerencia solo puede resolver lo que conoce — ir directo a ella evita que los problemas pequeños crezcan."},"example":{"en":"A coworker keeps skipping their side work? Bring it to your manager instead of letting it build up.","es":"¿Un compañero sigue sin hacer su trabajo de apoyo? Llévalo a tu gerente en vez de dejar que se acumule."}}$IG$::jsonb, updated_at = now() where id = 'e45a40e7-0c50-48f7-b8fc-101b80c19e50';


-- ════════ Your Schedule & Team Apps ════════

-- Your schedule posts in 7shifts by Thursday for next week.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Download 7shifts","es":"Descarga 7shifts"},"sub":{"en":"Set up your account during onboarding","es":"Configura tu cuenta durante la incorporación"}},{"title":{"en":"Use it actively","es":"Úsala activamente"},"sub":{"en":"Next week's schedule posts by Thursday","es":"El horario de la semana siguiente se publica a más tardar el jueves"}},{"title":{"en":"Know your shifts","es":"Conoce tus turnos"},"sub":{"en":"That's your responsibility","es":"Es tu responsabilidad"}}],"note":{"en":"Not checking the app is not an acceptable reason for missing a shift.","es":"No revisar la aplicación no es una razón aceptable para faltar a un turno."},"noteTone":"warn","why":{"en":"A set posting day means you always know when to look — and have time to plan around next week.","es":"Un día fijo de publicación significa que siempre sabes cuándo revisar — y tienes tiempo para planear la semana siguiente."},"example":{"en":"Make it a Thursday habit: open 7shifts and check next week's shifts.","es":"Hazlo un hábito cada jueves: abre 7shifts y revisa tus turnos de la semana siguiente."}}$IG$::jsonb, updated_at = now() where id = '0eae1b11-0bee-4ccb-b123-69099f2c8b36';

-- Your 7shifts schedule stands unless a manager confirms changes in writing.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Verbal conversation","es":"Conversación verbal"},"icon":"chat","lines":[{"en":"Doesn't override 7shifts","es":"No anula lo publicado en 7shifts"},{"en":"Your posted shift still stands","es":"Tu turno publicado se mantiene"}]},"right":{"title":{"en":"Manager confirms in writing","es":"Un gerente confirma por escrito"},"icon":"check","lines":[{"en":"Now the change counts","es":"Ahora el cambio cuenta"}]},"note":{"en":"Agreed on a change? Make sure a manager confirms it in writing.","es":"¿Acordaron un cambio? Asegúrate de que un gerente lo confirme por escrito."},"why":{"en":"Written confirmation keeps you, your teammates, and your manager working from the same schedule.","es":"La confirmación por escrito hace que tú, tus compañeros y tu gerente trabajen con el mismo horario."},"example":{"en":"A manager says “sure, leave at 8” in passing? Until it's confirmed in writing, your 7shifts shift still stands.","es":"¿Un gerente te dice de pasada “sí, vete a las 8”? Hasta que lo confirme por escrito, tu turno en 7shifts se mantiene."}}$IG$::jsonb, updated_at = now() where id = '815f0d96-1234-4b1f-b737-92f4b4a57054';

-- Limited availability may affect how many hours you’re offered.
update handbook_cards set infographic = $IG${"type":"icon","icon":"calendar","phrase":{"en":"Weigh it before you limit your availability in 7shifts","es":"Piénsalo antes de limitar tu disponibilidad en 7shifts"},"why":{"en":"The schedule is built from the times you're open — fewer open times may leave fewer shifts that fit you.","es":"El horario se arma con las horas en que estás disponible — menos horas disponibles pueden dejar menos turnos que te queden."},"example":{"en":"Switching to weekends only? You may be offered fewer hours than before.","es":"¿Vas a cambiar a solo fines de semana? Puede que se te ofrezcan menos horas que antes."}}$IG$::jsonb, updated_at = now() where id = '9957e576-33a1-4993-8faf-122e980beca3';

-- Telegram is our team’s main channel — check it regularly.
update handbook_cards set infographic = $IG${"type":"icon","icon":"chat","phrase":{"en":"Where management shares announcements and updates","es":"Donde la gerencia comparte anuncios y actualizaciones"},"sub":{"en":"You'll be added to the right Telegram groups during onboarding.","es":"Te agregarán a los grupos de Telegram apropiados durante la incorporación."},"note":{"en":"Checking Telegram regularly is part of the job.","es":"Revisar Telegram regularmente es parte del trabajo."},"why":{"en":"One channel means everyone hears the same news at the same time — nobody's left out of the loop.","es":"Un solo canal significa que todos se enteran de lo mismo al mismo tiempo — nadie se queda fuera."},"example":{"en":"Management posts a menu update in Telegram that morning — check it and you walk into your shift already knowing.","es":"La gerencia publica un cambio en el menú por Telegram esa mañana — si lo revisas, llegas a tu turno ya sabiéndolo."}}$IG$::jsonb, updated_at = now() where id = '906b6e90-0efc-4655-90a6-1d5e380c7698';

-- Keep Telegram professional — it’s not social media.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Clear","es":"Claro"},{"en":"Respectful","es":"Respetuoso"},{"en":"On topic","es":"En tema"}],"badge":{"en":"Every message","es":"En cada mensaje"},"note":{"en":"Use the same professionalism we expect from you on the floor.","es":"Usa el mismo profesionalismo que esperamos de ti en el piso."},"why":{"en":"Telegram is work, not a group chat — how we write there is part of how we treat each other.","es":"Telegram es trabajo, no un chat de amigos — cómo escribimos ahí es parte de cómo nos tratamos."},"example":{"en":"A clear, polite heads-up about your station belongs in Telegram; memes and side chatter don't.","es":"Un aviso claro y respetuoso sobre tu estación va en Telegram; los memes y las conversaciones fuera de tema no."}}$IG$::jsonb, updated_at = now() where id = '5a95b4fa-1602-4b0e-bdd6-1d34fd82f1bc';

-- Your pay stubs and tax documents live in the Paychex app.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Download the Paychex app","es":"Descarga la app de Paychex"},{"en":"Keep your account active","es":"Mantén tu cuenta activa"},{"en":"Manage your direct deposit","es":"Maneja tu depósito directo"},{"en":"Update your personal information","es":"Actualiza tu información personal"}],"why":{"en":"Everything about your pay lives in one place you control.","es":"Todo lo relacionado con tu pago está en un solo lugar que tú controlas."},"example":{"en":"Moved? Update your address in the Paychex app.","es":"¿Te mudaste? Actualiza tu dirección en la app de Paychex."}}$IG$::jsonb, updated_at = now() where id = '889ab545-ed42-49a2-950a-4ad4fc023d9b';

-- When systems change, you’ll be trained — and expected to adopt them.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"A system changes","es":"Un sistema cambia"},"sub":{"en":"We're growing, so our tools will evolve too","es":"Estamos creciendo, así que nuestras herramientas también evolucionarán"}},{"title":{"en":"You're notified and trained","es":"Se te notifica y capacita"},"sub":{"en":"Everything you need to transition smoothly","es":"Todo lo necesario para hacer la transición sin problemas"}},{"title":{"en":"You adopt it","es":"Lo adoptas"}}],"note":{"en":"Resisting required systems is treated as a conduct issue, not a preference.","es":"La resistencia a adoptar los sistemas requeridos se trata como un problema de conducta, no como una preferencia."},"noteTone":"warn","why":{"en":"One team on one system is what lets every shift run the same way, no matter who's working.","es":"Un equipo con un mismo sistema es lo que permite que cada turno funcione igual, sin importar quién trabaje."},"example":{"en":"A new checkout process rolls out? You'll be trained on it — then that's the way checkout gets done.","es":"¿Llega un nuevo proceso de cierre de turno? Recibirás capacitación — y desde ahí, así se hace el cierre."}}$IG$::jsonb, updated_at = now() where id = '7755257f-0010-4c71-a81c-9d7c489e9cfb';


-- ════════ Raises & Growth ════════

-- Your review happens around your work anniversary.
update handbook_cards set infographic = $IG${"type":"icon","icon":"calendar","phrase":{"en":"Tied to your hire date","es":"Ligada a tu fecha de contratación"},"sub":{"en":"Not a company-wide calendar, and not all at once with everyone else. Every evaluation results in a conversation.","es":"No a un calendario general de la compañía, ni al mismo tiempo que todos los demás. Cada evaluación resulta en una conversación."},"note":{"en":"An evaluation is not a guarantee of a raise — not every conversation results in a pay increase.","es":"Una evaluación no es una garantía de aumento — no toda conversación resulta en un aumento de pago."},"noteTone":"info","why":{"en":"Your review should be about your own progress, on your own timeline — not squeezed in with everyone else's.","es":"Tu evaluación debe tratarse de tu propio progreso, en tu propio tiempo — no apretada entre las de todos los demás."},"example":{"en":"Hired in June? Your review comes around your June anniversary — not in one big company-wide round.","es":"¿Te contrataron en junio? Tu evaluación será alrededor de tu aniversario en junio — no en una ronda general de la compañía."}}$IG$::jsonb, updated_at = now() where id = 'ca3df3dc-d2f4-4877-93b5-75797fe1c227';

-- Five things decide whether you’re ready for a raise.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Reliability","es":"Confiabilidad"},{"en":"Professional conduct","es":"Conducta profesional"},{"en":"Urgency & work ethic","es":"Urgencia y ética de trabajo"},{"en":"Coachability","es":"Capacidad de recibir retroalimentación"},{"en":"Skill level — speed, accuracy, POS, station control, menu knowledge","es":"Nivel de habilidad — velocidad, precisión, POS, control de estación, conocimiento del menú"}],"badge":{"en":"Skill is only 1 of 5","es":"La habilidad es solo 1 de 5"},"note":{"en":"Talented but unreliable, or skilled but resistant to coaching, is not raise-ready. A track record of dependability is non-negotiable for advancement.","es":"Talentoso pero poco confiable, o hábil pero resistente a recibir orientación, no está listo para un aumento. Un historial de confiabilidad es innegociable para avanzar."},"why":{"en":"Skill shows what you can do on your best night; the other four show whether the team can count on you every night.","es":"La habilidad muestra lo que puedes hacer en tu mejor noche; las otras cuatro muestran si el equipo puede contar contigo todas las noches."},"example":{"en":"A server who knows the whole menu but pushes back on every correction isn't raise-ready yet.","es":"Un mesero que se sabe todo el menú pero rechaza cada corrección todavía no está listo para un aumento."}}$IG$::jsonb, updated_at = now() where id = 'b861eecf-d799-4d23-b5e3-016484bcc743';

-- Every shift counts — not just when ownership is watching.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"How you communicate with teammates and guests","es":"Cómo te comunicas con compañeros y clientes"},{"en":"How you handle pressure","es":"Cómo manejas la presión"},{"en":"Contributing to a positive team environment","es":"Contribuir a un ambiente positivo de equipo"},{"en":"Staying active and aware during slow periods","es":"Mantenerte activo y atento en los períodos tranquilos"},{"en":"Helping teammates when they're in the weeds","es":"Ayudar a tus compañeros cuando estén ahogados de trabajo"}],"badge":{"en":"All of it counts","es":"Todo cuenta"},"note":{"en":"Urgency and ownership are watched consistently — not just during evaluations.","es":"La urgencia y la responsabilidad se observan constantemente — no solo durante las evaluaciones."},"noteTone":"info","why":{"en":"Guests and teammates feel how you work on an ordinary Tuesday, not just on the day someone's evaluating you.","es":"Los clientes y compañeros sienten cómo trabajas un martes cualquiera, no solo el día en que alguien te está evaluando."},"example":{"en":"Slow at 3:00? Restock, wipe down, or jump in for the teammate buried in to-go orders.","es":"¿Está tranquilo a las 3:00? Reabastece, limpia o ayuda al compañero que está ahogado con pedidos para llevar."}}$IG$::jsonb, updated_at = now() where id = '1ac4cdf3-7bdb-4567-a679-140d25277e69';

-- How you take feedback says a lot about how far you’ll grow.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Accept the correction","es":"Acepta la corrección"},"sub":{"en":"Hear it out instead of arguing the redirect","es":"Escúchala en vez de discutirla"}},{"title":{"en":"Make the adjustment","es":"Haz el ajuste"}},{"title":{"en":"Move forward","es":"Sigue adelante"}}],"note":{"en":"Coachable employees grow faster than talented ones who argue every redirect — it's one of the strongest predictors of long-term success here.","es":"Los empleados que aceptan la corrección crecen más rápido que los talentosos que discuten cada corrección — es uno de los indicadores más fuertes de éxito a largo plazo aquí."},"noteTone":"info","why":{"en":"A correction is a shortcut — someone is handing you what took them years to learn.","es":"Una corrección es un atajo — alguien te está dando lo que le tomó años aprender."},"example":{"en":"The sushi chef says your rolls are too loose — say “got it,” tighten the next one, and keep going.","es":"El chef de sushi te dice que tus rollos están muy flojos — di “entendido”, aprieta el siguiente y sigue adelante."}}$IG$::jsonb, updated_at = now() where id = '79cd6464-f7bd-4992-8857-62975c954c05';

-- Time alone doesn’t raise your pay — consistent value does.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"A raise is","es":"Un aumento es"},"icon":"growth","lines":[{"en":"An investment","es":"Una inversión"},{"en":"We believe you consistently produce value that justifies higher pay","es":"Creemos que produces valor constantemente a un nivel que justifica un pago más alto"}]},"right":{"title":{"en":"A raise isn't","es":"Un aumento no es"},"icon":"x","lines":[{"en":"On a set calendar","es":"Según un calendario fijo"},{"en":"Just because time has passed","es":"Solo porque ha pasado el tiempo"},{"en":"A sympathy adjustment","es":"Un ajuste por simpatía"},{"en":"A reward for asking confidently","es":"Una recompensa por pedirlo con confianza"}]},"note":{"en":"Longevity is respected — it just isn't a raise on its own.","es":"La antigüedad se respeta — pero por sí sola no es un aumento."},"noteTone":"info","why":{"en":"Pay is how we invest in the people who make every shift better, so it follows the value you bring.","es":"El pago es cómo invertimos en las personas que mejoran cada turno, así que sigue el valor que aportas."},"example":{"en":"Two years on the job doesn't trigger a raise by itself — consistently running a clean, fast station is what makes the case.","es":"Dos años en el puesto no generan un aumento por sí solos — mantener tu estación limpia y rápida de forma constante es lo que lo justifica."}}$IG$::jsonb, updated_at = now() where id = '6ccc5a14-4282-44df-b7cf-8dfe795e2134';

-- No raise this time? You’ll get a clear map forward.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"The specific category holding you back — not a vague “not yet”","es":"La categoría específica que te está deteniendo — no un vago “todavía no”"},{"en":"What improvement needs to look like","es":"Cómo debe verse la mejora"},{"en":"The timeline for your re-evaluation","es":"El plazo para tu re-evaluación"}],"badge":{"en":"You'll get all 3","es":"Recibirás las 3"},"note":{"en":"A denial isn't a dead end. It's a map — use it.","es":"Una negación no es un callejón sin salida. Es un mapa — úsalo."},"noteTone":"info","why":{"en":"A vague “not yet” helps no one; a specific answer gives you something real to work on.","es":"Un vago “todavía no” no le sirve a nadie; una respuesta específica te da algo real en qué trabajar."},"example":{"en":"Told coachability is holding you back? You'll know what better looks like — and when you'll be re-evaluated.","es":"¿Te dijeron que la capacidad de recibir orientación te está deteniendo? Sabrás cómo se ve la mejora — y cuándo te re-evaluarán."}}$IG$::jsonb, updated_at = now() where id = '41d94836-a6ef-4f05-a23b-54c809147088';

-- Hard work earns respect. Leading correctly earns trust. We look for both.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"How you work","es":"Cómo trabajas"},"icon":"star","lines":[{"en":"Hard work and job performance","es":"Trabajo duro y desempeño laboral"},{"en":"Earns respect","es":"Gana respeto"}]},"right":{"title":{"en":"How you lead","es":"Cómo lideras"},"icon":"users","lines":[{"en":"Handling conflict and stress","es":"Manejar los conflictos y el estrés"},{"en":"Enforcing standards when no one's watching","es":"Hacer cumplir los estándares cuando nadie está observando"},{"en":"Making the team better","es":"Hacer que el equipo sea mejor"},{"en":"Earns trust","es":"Gana confianza"}]},"note":{"en":"Promotion looks beyond job performance — at how you influence the people around you. Leadership roles are earned and carry real responsibility.","es":"Un ascenso mira más allá del desempeño laboral — a cómo influyes en las personas a tu alrededor. Los roles de liderazgo se ganan y conllevan una responsabilidad real."},"noteTone":"info","why":{"en":"Leaders shape how an entire shift runs, so we promote the people who already make others better.","es":"Los líderes marcan cómo funciona todo un turno, por eso ascendemos a quienes ya hacen mejores a los demás."},"example":{"en":"Holding the closing checklist to standard on a night ownership isn't in the building is exactly what we look for in a leader.","es":"Cumplir la lista de cierre al pie de la letra una noche en que los propietarios no están es exactamente lo que buscamos en un líder."}}$IG$::jsonb, updated_at = now() where id = 'af710fc7-95e9-4425-adde-c1e08c51c26b';

-- At the upper range for your position, growth means taking on more.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Expanded responsibilities","es":"Responsabilidades expandidas"},{"en":"Cross-training","es":"Capacitación cruzada"},{"en":"Promotion into a higher-level position","es":"Un ascenso a una posición de nivel más alto"}],"badge":{"en":"3 ways to keep growing","es":"3 formas de seguir creciendo"},"note":{"en":"Once you reach the upper range for your position, further growth requires one of these.","es":"Una vez que alcanzas el rango superior de tu posición, seguir creciendo requiere una de estas."},"why":{"en":"Every position has a top end — taking on more is how you keep growing beyond it.","es":"Cada posición tiene un tope — asumir más es cómo sigues creciendo más allá de él."},"example":{"en":"A server at the top of their range might cross-train as a host, or take on training new servers.","es":"Un mesero en el tope de su rango podría capacitarse también como anfitrión, o encargarse de entrenar a meseros nuevos."}}$IG$::jsonb, updated_at = now() where id = '87980f6c-a778-428f-818d-837a0ea52085';

-- Questions about your pay or review? Go straight to your manager.
update handbook_cards set infographic = $IG${"type":"icon","icon":"clipboard","phrase":{"en":"Raise and promotion decisions are documented","es":"Las decisiones de aumentos y ascensos se documentan"},"sub":{"en":"Internally, to keep things consistent.","es":"Internamente, para asegurar consistencia."},"why":{"en":"Your manager sees your work every shift, so they're the right place to start.","es":"Tu gerente ve tu trabajo en cada turno, así que es el lugar correcto para empezar."},"example":{"en":"Unsure how your last review was decided? Bring it straight to your manager.","es":"¿No estás seguro de cómo se decidió tu última evaluación? Llévalo directo con tu gerente."}}$IG$::jsonb, updated_at = now() where id = 'fb885143-bc6f-4985-90f1-d3de7f77833b';


-- ════════ Harassment & Conduct ════════

-- Discrimination has no place in any of our restaurants.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Job decisions are based on","es":"Las decisiones de empleo se basan en"},"icon":"check","lines":[{"en":"Performance","es":"Desempeño"},{"en":"Qualifications","es":"Calificaciones"},{"en":"Behavior","es":"Comportamiento"},{"en":"Business need","es":"Necesidades del negocio"}]},"right":{"title":{"en":"Never based on","es":"Nunca en"},"icon":"x","lines":[{"en":"Race, color, religion, sex, pregnancy","es":"Raza, color, religión, sexo, embarazo"},{"en":"Sexual orientation, gender identity, national origin","es":"Orientación sexual, identidad de género, origen nacional"},{"en":"Age, disability, genetic information","es":"Edad, discapacidad, información genética"},{"en":"Veteran status, military duty","es":"Estado de veterano, servicio militar"},{"en":"Any other legally protected characteristic","es":"Cualquier otra característica protegida por la ley"}]},"why":{"en":"Everyone on this team deserves to be judged by their work and conduct — never by who they are.","es":"Todos en este equipo merecen ser juzgados por su trabajo y su conducta — nunca por quiénes son."}}$IG$::jsonb, updated_at = now() where id = '19b8818c-b0e8-4ffa-a72f-f53b382edd5b';

-- With harassment, impact matters more than intent.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Words","es":"Palabras"},"icon":"chat","lines":[{"en":"Slurs or offensive jokes","es":"Insultos o chistes ofensivos"},{"en":"Insulting nicknames or threats","es":"Apodos despectivos o amenazas"},{"en":"Unwanted comments about protected characteristics","es":"Comentarios no deseados sobre características protegidas"}]},"right":{"title":{"en":"Visual & physical","es":"Visual y física"},"icon":"hand","lines":[{"en":"Offensive images, gestures, or written material","es":"Imágenes ofensivas, gestos o material escrito"},{"en":"Unwanted touching or blocking someone's way","es":"Contacto no deseado o bloquearle el paso a alguien"},{"en":"Any physical aggression","es":"Cualquier agresión física"}]},"note":{"en":"Mockery and persistent unwanted attention count too. Saying you didn't mean it doesn't change it — harassment counts regardless of intent.","es":"Las burlas y la atención persistente no deseada también cuentan. Decir que no fue tu intención no lo cambia — el acoso cuenta independientemente de la intención."},"noteTone":"warn","why":{"en":"Everyone here deserves to feel safe at work, and it's the person on the receiving end who lives with the impact.","es":"Todos aquí merecen sentirse seguros en el trabajo, y es la persona que lo recibe quien vive con el impacto."},"example":{"en":"A nickname that mocks a coworker's accent counts — even if you meant it as a joke.","es":"Un apodo que se burla del acento de un compañero cuenta — aunque lo hayas dicho en broma."}}$IG$::jsonb, updated_at = now() where id = 'c0646a6b-8bc8-431b-9119-8a2544fddb02';

-- Unwelcome and sexual? No gray area — it's not okay here.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Unwelcome advances or propositions","es":"Insinuaciones o propuestas no deseadas"},{"en":"Requests for sexual favors","es":"Pedir favores sexuales"},{"en":"Inappropriate comments or crude sexual jokes","es":"Comentarios inapropiados o chistes sexuales vulgares"},{"en":"Sharing explicit images","es":"Compartir imágenes explícitas"},{"en":"Anything a reasonable person would find sexually offensive","es":"Cualquier cosa que una persona razonable consideraría sexualmente ofensiva"}],"why":{"en":"Everyone should be able to do their job without being made to feel uncomfortable or unsafe.","es":"Todos deben poder hacer su trabajo sin que los hagan sentir incómodos o inseguros."},"mark":"x","badge":{"en":"Never okay here","es":"Nunca está bien aquí"}}$IG$::jsonb, updated_at = now() where id = '994daef4-19d8-42d2-9533-10110f3be868';

-- Zero tolerance for violence or threats of any kind.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Assault or physical contact meant to harm or intimidate","es":"Agresión o contacto físico con intención de dañar o intimidar"},{"en":"Spoken or written threats","es":"Amenazas habladas o escritas"},{"en":"Anything that makes someone reasonably fear harm is coming","es":"Cualquier cosa que haga que alguien razonablemente tema que le harán daño"},{"en":"Firearms or weapons on Company property — except as permitted by applicable state law","es":"Armas de fuego u otras armas en propiedad de la Compañía — excepto lo que permita la ley estatal aplicable"}],"note":{"en":"Violations may mean immediate termination and referral to law enforcement — the usual discipline steps don't apply here.","es":"Las violaciones pueden resultar en terminación inmediata y referencia a las autoridades — aquí no se pasa por los pasos de disciplina progresiva."},"noteTone":"warn","why":{"en":"Everyone here has to feel safe at work — a single act of violence or threat breaks that for the whole team.","es":"Todos aquí tienen que sentirse seguros en el trabajo — un solo acto de violencia o una amenaza rompe eso para todo el equipo."},"mark":"x","badge":{"en":"Zero tolerance","es":"Cero tolerancia"}}$IG$::jsonb, updated_at = now() where id = 'c089828b-9694-4297-9b6d-943d6e213dcc';

-- Something feels wrong? Tell us — you don't need to be sure.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Tell the manager on duty","es":"Avisa al gerente en turno"},"sub":{"en":"Experienced it or saw it? As soon as possible.","es":"¿Lo viviste o lo viste? Lo antes posible."}},{"title":{"en":"Or go to the General Manager","es":"O ve con el Gerente General"},"sub":{"en":"If your manager is the concern, or you're uncomfortable telling them","es":"Si tu gerente es la fuente del problema, o te incomoda reportarle"}},{"title":{"en":"Contact ownership via Telegram","es":"Contacta a los propietarios vía Telegram"},"sub":{"en":"If it involves the General Manager, or it's still unresolved","es":"Si involucra al Gerente General o sigue sin resolverse"}},{"title":{"en":"Contact HR through Paychex","es":"Contacta a Recursos Humanos a través de Paychex"},"sub":{"en":"If the concern involves ownership — for an independent review","es":"Si la preocupación involucra a los propietarios — para una revisión independiente"}}],"why":{"en":"We can only fix what we know about — and whoever the concern involves, there's a path around them.","es":"Solo podemos corregir lo que sabemos — e involucre a quien involucre, hay un camino que no pasa por esa persona."},"example":{"en":"If the manager on duty is the one making you uncomfortable, skip them and go straight to the General Manager.","es":"Si el gerente en turno es quien te hace sentir incómodo, no pases por él y ve directo al Gerente General."}}$IG$::jsonb, updated_at = now() where id = 'bfb8da79-67ff-4e31-9d57-4933c13c0565';

-- Every report is investigated — as confidentially as possible.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Every report is looked into","es":"Cada reporte se investiga"},"sub":{"en":"Promptly and thoroughly","es":"De manera pronta y exhaustiva"}},{"title":{"en":"Interviewed? Cooperate fully","es":"¿Te entrevistan? Coopera completamente"},"sub":{"en":"You're expected to give honest information","es":"Se espera que des información honesta"}},{"title":{"en":"Complaint substantiated?","es":"¿Se comprueba la queja?"},"sub":{"en":"Corrective action will follow","es":"Seguirá una acción correctiva"}}],"note":{"en":"Managers who see or are told about harassment and fail to act can be disciplined too.","es":"Los gerentes que presencien o sean informados de acoso y no actúen también están sujetos a disciplina."},"noteTone":"warn","why":{"en":"Reporting only works if people trust it's taken seriously, so every report gets a real look.","es":"Reportar solo funciona si la gente confía en que se toma en serio, por eso cada reporte recibe una revisión real."},"example":{"en":"Asked what you saw during a closing shift? Share it fully and honestly — even if it involves a friend.","es":"¿Te preguntan qué viste durante un turno de cierre? Cuéntalo completo y con honestidad — aunque involucre a un amigo."}}$IG$::jsonb, updated_at = now() where id = 'b734dbd3-5ed7-4a38-bb6a-0c9cdd54ebf9';

-- You won't face retaliation for speaking up.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Protected","es":"Está protegido"},"icon":"shield","lines":[{"en":"Reporting a concern","es":"Reportar una preocupación"},{"en":"Taking part in an investigation","es":"Participar en una investigación"},{"en":"Supporting a coworker who reported in good faith","es":"Apoyar a un compañero que hizo un reporte de buena fe"}]},"right":{"title":{"en":"Retaliation includes","es":"Las represalias incluyen"},"icon":"x","lines":[{"en":"Schedule cuts","es":"Reducción de horarios"},{"en":"Unfavorable assignments","es":"Asignaciones desfavorables"},{"en":"Exclusion","es":"Exclusión"},{"en":"Any adverse treatment tied to a report","es":"Cualquier trato adverso vinculado a un reporte"}]},"note":{"en":"Knowingly filing a false complaint to harm another employee is also a violation subject to discipline.","es":"Presentar a sabiendas una queja falsa para perjudicar a otro empleado también es una violación sujeta a disciplina."},"noteTone":"warn","why":{"en":"People only speak up when it's safe to — and we need to hear about problems to fix them.","es":"La gente solo habla cuando es seguro hacerlo — y necesitamos enterarnos de los problemas para corregirlos."},"example":{"en":"Backed up a coworker's report last month? Your hours and sections can't be cut or made worse because of it.","es":"¿Apoyaste el reporte de un compañero el mes pasado? Tus horas y secciones no pueden reducirse ni empeorar por eso."}}$IG$::jsonb, updated_at = now() where id = '28d22022-def1-413c-98c2-d70f81638885';

-- Not every clash is harassment — work it out professionally.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Address it directly and professionally","es":"Abórdalo directamente y con profesionalismo"},{"en":"Or ask a manager to help","es":"O pide ayuda a un gerente"}],"dont":[{"en":"Let it spill onto the floor","es":"Dejar que se derrame en el piso"},{"en":"Vent to other coworkers","es":"Desahogarte con otros compañeros"},{"en":"Let it fester until it affects the whole team","es":"Dejar que se acumule hasta afectar a todo el equipo"}],"why":{"en":"Friction happens in a busy restaurant — handled early and directly, it stays small.","es":"Los roces pasan en un restaurante ocupado — si se manejan temprano y de frente, se quedan pequeños."},"example":{"en":"Disagree with a coworker about side work? Talk it through after the rush — not in front of guests or the rest of the team.","es":"¿Tienes un desacuerdo con un compañero sobre las tareas secundarias? Háblenlo después de la hora pico — no frente a los clientes ni al resto del equipo."}}$IG$::jsonb, updated_at = now() where id = 'e6738cc1-ed55-4727-9857-538e69d30e3c';

-- Leaving? We ask for at least two weeks' notice.
update handbook_cards set infographic = $IG${"type":"stat","value":"2","unit":{"en":"weeks","es":"semanas"},"label":{"en":"The notice we ask for when you resign","es":"El aviso que pedimos cuando renuncias"},"sub":{"en":"Employment may end by resignation, termination by the Company, job abandonment, or mutual agreement. How you leave says something — make it say the right thing.","es":"El empleo puede terminar por renuncia voluntaria, terminación por parte de la Compañía, abandono de trabajo o acuerdo mutuo. Cómo te vas dice algo — haz que diga lo correcto."},"icon":"door","footer":{"tone":"warn","text":{"en":"Two or more no call / no shows in a row, with no verified emergency, is job abandonment — treated as a voluntary resignation.","es":"Dos o más veces seguidas sin presentarte ni avisar, sin una emergencia verificada, es abandono de trabajo — se trata como una renuncia voluntaria."}},"why":{"en":"Two weeks gives your manager time to cover your shifts, so your teammates aren't left short.","es":"Dos semanas le dan a tu gerente tiempo para cubrir tus turnos, para que tus compañeros no se queden cortos."},"example":{"en":"Last day Saturday the 18th? Give notice by Saturday the 4th.","es":"¿Tu último día es el sábado 18? Avisa a más tardar el sábado 4."}}$IG$::jsonb, updated_at = now() where id = 'b277a019-35f5-4856-9723-0e7f6ae4e4b0';


-- ════════ Safety & Emergencies ════════

-- Safety is part of your job — every shift.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Wear non-slip shoes","es":"Usa calzado antideslizante"},{"en":"Keep walkways, exits, and service paths clear of trip hazards","es":"Mantén pasillos, salidas y rutas de servicio libres de peligros de tropiezo"},{"en":"Use equipment only as intended — and only if you're trained on it","es":"Usa el equipo solo para su propósito — y solo si te han capacitado"},{"en":"Bend at the knees, keep the load close — ask for help if it's too heavy","es":"Dobla las rodillas, mantén la carga cerca — pide ayuda si pesa demasiado"}],"note":{"en":"See an unsafe condition? Report it to a manager immediately — before someone gets hurt.","es":"¿Ves una condición insegura? Repórtala a un gerente inmediatamente — antes de que alguien se lastime."},"why":{"en":"A slip or a strained back can take a teammate off the line — and the whole team feels it.","es":"Un resbalón o una espalda lastimada puede sacar a un compañero de la línea — y todo el equipo lo siente."},"example":{"en":"Floor mat curling up by the dish pit? Tell a manager now, not after someone trips on it.","es":"¿El tapete junto al área de lavado se está levantando? Avísale a un gerente ahora, no después de que alguien se tropiece."},"noteTone":"info"}$IG$::jsonb, updated_at = now() where id = 'f2b7917e-aff9-4267-96fe-2f2dabccfabf';

-- Knives, heat, and spills get your full attention.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Always cut away from your body","es":"Siempre corta en dirección opuesta a tu cuerpo"},{"en":"Use oven mitts for hot cookware","es":"Usa guantes de horno con utensilios calientes"},{"en":"Call out “hot” or “behind” when moving with anything hot or sharp","es":"Avisa “caliente” o “atrás” al moverte con algo caliente o filoso"},{"en":"Clean up spills immediately","es":"Limpia los derrames inmediatamente"}],"dont":[{"en":"Rush knife work","es":"Apresurar el trabajo con cuchillos"},{"en":"Leave blades exposed","es":"Dejar cuchillas expuestas"},{"en":"Leave cooking food unattended on a flame or burner","es":"Dejar comida cocinándose sin atención en una llama o quemador"}],"note":{"en":"Know where the fire extinguishers, first aid kits, and emergency shutoffs are at your location.","es":"Ten presente dónde están los extintores, los botiquines de primeros auxilios y las desconexiones de emergencia de tu ubicación."},"why":{"en":"Our kitchens are fast and tight — one exposed blade or unannounced hot pan can hurt someone who never saw it coming.","es":"Nuestras cocinas son rápidas y estrechas — una cuchilla expuesta o un sartén caliente sin avisar puede lastimar a alguien que nunca lo vio venir."},"example":{"en":"Carrying a hot pan past a teammate on the line? Call out “hot” and “behind” before you pass, not after.","es":"¿Llevas un sartén caliente detrás de un compañero en la línea? Avisa “caliente” y “atrás” antes de pasar, no después."},"noteTone":"info"}$IG$::jsonb, updated_at = now() where id = '4e89be6e-164a-434b-ac09-fe59e60d6f00';

-- Never mix chemicals — mixed cleaning products can create toxic fumes.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Use chemicals only as directed","es":"Usa los productos químicos solo como se indica"},{"en":"Store them properly labeled, in designated areas","es":"Almacénalos debidamente etiquetados, en áreas designadas"},{"en":"Keep them away from food and food-contact surfaces","es":"Mantenlos lejos de alimentos y superficies en contacto con alimentos"}],"dont":[{"en":"Mix chemicals","es":"Mezclar productos químicos"},{"en":"Improvise concentrations or applications","es":"Improvisar concentraciones o aplicaciones"}],"note":{"en":"Need details on a chemical? Safety Data Sheets (SDS) are available from your manager.","es":"¿Necesitas información de un producto? Las Hojas de Datos de Seguridad (SDS) están disponibles con tu gerente."},"noteTone":"info","why":{"en":"Cleaning products are safe when used as directed — improvising is how people get hurt and food gets contaminated.","es":"Los productos de limpieza son seguros si se usan como se indica — improvisar es como la gente se lastima y la comida se contamina."},"example":{"en":"Sanitizer bucket seems weak? Don't add a splash of bleach — remake it as directed.","es":"¿La cubeta de sanitizante parece débil? No le agregues un chorro de cloro — prepárala de nuevo como se indica."}}$IG$::jsonb, updated_at = now() where id = '938ac914-2123-4a97-8e73-d5366211ec9f';

-- Report every injury or accident right away — even minor ones.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Tell the manager on duty","es":"Avísale al gerente en turno"},"sub":{"en":"Immediately — even if it's minor","es":"Inmediatamente — aunque sea menor"}},{"title":{"en":"Get first aid or medical care","es":"Busca primeros auxilios o atención médica"},"sub":{"en":"As needed — don't keep working if you're injured","es":"Según sea necesario — no sigas trabajando si estás lesionado"}},{"title":{"en":"Complete an Accident Report","es":"Completa un Reporte de Accidente"},"sub":{"en":"The same day: what, when, where, how, and who saw it","es":"El mismo día: qué pasó, cuándo, dónde, cómo y quién fue testigo"}}],"note":{"en":"Workers' comp: you may be entitled to benefits for medical treatment and lost wages — but only for injuries reported promptly and properly documented.","es":"Compensación de trabajadores: puedes tener derecho a beneficios por tratamiento médico y salarios perdidos — pero solo para lesiones reportadas puntualmente y documentadas apropiadamente."},"noteTone":"warn","why":{"en":"A small injury can get worse later — a prompt report gets you care now and puts the record in place if you need it.","es":"Una lesión pequeña puede empeorar después — reportarla a tiempo te da atención ahora y deja el registro listo si lo necesitas."},"example":{"en":"Cut your finger during prep at 3:00? Tell the manager on duty, get it cleaned and bandaged, and complete the Accident Report that same day.","es":"¿Te cortaste un dedo en la preparación a las 3:00? Avísale al gerente en turno, límpialo y véndalo, y completa el Reporte de Accidente ese mismo día."}}$IG$::jsonb, updated_at = now() where id = '224eb1ee-6a89-40ec-8d6e-b63cb3fe24be';

-- Guest gets hurt? Get the manager — don’t admit fault.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Notify the manager on duty immediately","es":"Notifica al gerente en turno inmediatamente"}],"dont":[{"en":"Admit fault","es":"Admitir culpa"},{"en":"Make statements about liability","es":"Hacer declaraciones sobre responsabilidad"}],"why":{"en":"The manager on duty takes it from there — a well-meant “that was our fault” can create liability questions for the Company.","es":"El gerente en turno se encarga a partir de ahí — un “fue nuestra culpa” bien intencionado puede crear problemas de responsabilidad para la Compañía."},"example":{"en":"A guest trips near the host stand? Get the manager right away — you can ask “Are you okay?” but don't say “That's our fault.”","es":"¿Un cliente se tropieza cerca de la recepción? Busca al gerente de inmediato — puedes preguntar “¿Está bien?” pero no digas “Es nuestra culpa.”"}}$IG$::jsonb, updated_at = now() where id = '0a7bf066-aa94-479a-aaf7-2e8f2fb74f88';

-- In an emergency, alert the manager and call 911.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Alert the manager, call 911","es":"Alerta al gerente, llama al 911"},"sub":{"en":"Immediately, if there's any risk to life or property","es":"Inmediatamente, si hay algún riesgo para la vida o la propiedad"}},{"title":{"en":"Help guests exit safely","es":"Ayuda a los clientes a salir"},"sub":{"en":"Only if you can do it without risk to yourself","es":"Solo si puedes hacerlo sin riesgo para ti"}},{"title":{"en":"Gather at the meeting point","es":"Reúnete en el punto de encuentro"},"sub":{"en":"The designated spot outside. No elevators in a fire. Don't re-enter until cleared.","es":"El punto designado afuera. No uses elevadores en un incendio. No vuelvas a entrar hasta que te autoricen."}}],"note":{"en":"During your first week, find the emergency exits at your location.","es":"Durante tu primera semana, identifica las salidas de emergencia de tu ubicación."},"noteTone":"info","why":{"en":"In an emergency there's no time to figure it out — knowing the steps now means you act instead of freeze.","es":"En una emergencia no hay tiempo para pensarlo — conocer los pasos desde ahora te permite actuar en vez de paralizarte."}}$IG$::jsonb, updated_at = now() where id = '658978c5-59ac-4134-a33e-9aa9aa3fef65';

-- In a robbery or threat, your safety is the only priority.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Comply with any credible threat","es":"Cumple ante cualquier amenaza creíble"},"sub":{"en":"Don't resist or argue — no amount of money, equipment, or inventory is worth your life","es":"No resistas ni discutas — ninguna cantidad de dinero, equipo o inventario vale tu vida"}},{"title":{"en":"Call 911 once it's safe","es":"Llama al 911 cuando sea seguro"}},{"title":{"en":"Notify management and ownership","es":"Notifica a la gerencia y a los propietarios"},"sub":{"en":"Immediately after calling 911","es":"Inmediatamente después de llamar al 911"}}],"note":{"en":"Don't discuss the incident with coworkers, guests, or on social media — ownership handles all communication.","es":"No hables del incidente con otros empleados, clientes ni en redes sociales — los propietarios manejan toda la comunicación."},"why":{"en":"Everything in the building can be replaced. You can't.","es":"Todo lo que hay en el edificio se puede reemplazar. Tú no."},"noteTone":"info"}$IG$::jsonb, updated_at = now() where id = '05dd548a-b9d7-432e-828f-17fc7fa47e14';

-- Cameras in common work areas may record video and audio.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Where cameras may record","es":"Dónde pueden grabar"},"icon":"camera","lines":[{"en":"Dining room, bar, host stand","es":"Comedor, bar, recepción"},{"en":"Kitchen, cash areas, storage","es":"Cocina, áreas de caja, almacenamiento"},{"en":"Back of house","es":"Parte trasera"},{"en":"Parking lots and exteriors","es":"Estacionamientos y exteriores"}]},"right":{"title":{"en":"Not here","es":"Aquí no"},"icon":"x","lines":[{"en":"Restrooms","es":"Baños"},{"en":"Designated changing areas","es":"Áreas designadas para cambiarse"}]},"note":{"en":"By working here, you consent to this monitoring. Recordings may be reviewed for safety, security, and operations. Footage is confidential — only authorized management and ownership can access it.","es":"Al trabajar aquí, das tu consentimiento a este monitoreo. Las grabaciones pueden revisarse por seguridad, protección y operación. Son confidenciales — solo la gerencia autorizada y los propietarios pueden acceder a ellas."},"noteTone":"info","why":{"en":"Cameras help protect the team, our guests, and the business — and leave a clear record when something goes wrong.","es":"Las cámaras ayudan a proteger al equipo, a nuestros clientes y al negocio — y dejan un registro claro cuando algo sale mal."},"example":{"en":"A guest disputes a charge at the register? Management may review the cash-area footage to see what happened.","es":"¿Un cliente reclama un cobro en la caja? La gerencia puede revisar la grabación del área de caja para ver qué pasó."}}$IG$::jsonb, updated_at = now() where id = '10614f02-39e3-40fe-bb62-f496b4f6aed6';

-- Never cover, disable, or tamper with cameras or audio devices.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Leave cameras and audio devices as they are","es":"Deja las cámaras y los dispositivos de audio como están"}],"dont":[{"en":"Intentionally block a camera's view","es":"Obstruir intencionalmente la vista de una cámara"},{"en":"Access footage without authorization — or try to","es":"Acceder a grabaciones sin autorización — o intentarlo"},{"en":"Install personal or unauthorized recording devices on company property","es":"Instalar dispositivos de grabación personales o no autorizados en propiedad de la compañía"}],"note":{"en":"Violations may result in disciplinary action up to and including termination.","es":"Las violaciones pueden resultar en acción disciplinaria hasta e incluyendo la terminación."},"noteTone":"warn","why":{"en":"Cameras only protect the team when they're working and the footage stays secure.","es":"Las cámaras solo protegen al equipo cuando funcionan y las grabaciones se mantienen seguras."},"example":{"en":"Mounting your own camera in the back office to watch your things? That's an unauthorized recording device — not allowed.","es":"¿Instalar tu propia cámara en la oficina para cuidar tus cosas? Es un dispositivo de grabación no autorizado — no está permitido."}}$IG$::jsonb, updated_at = now() where id = '62c42c09-73c3-4e79-873e-620d70bc5907';


-- ════════ Drugs & Alcohol ════════

-- Zero tolerance: never work under the influence.
update handbook_cards set infographic = $IG${"type":"icon","icon":"noglass","phrase":{"en":"Clear-headed, every shift","es":"Con la mente clara, en cada turno"},"sub":{"en":"This covers alcohol, illegal drugs, or any controlled substance that impairs your ability to do your job.","es":"Esto incluye alcohol, drogas ilegales o cualquier sustancia controlada que afecte tu capacidad para realizar tu trabajo."},"note":{"en":"Arriving to or working a shift while impaired is grounds for immediate termination.","es":"Presentarte o trabajar un turno bajo los efectos es motivo de terminación inmediata."},"noteTone":"warn","why":{"en":"Open flames, sharp knives, and guests trusting us with their safety — impairment puts all of it at risk.","es":"Llamas abiertas, cuchillos filosos y clientes que confían en nosotros para su seguridad — trabajar bajo los efectos pone todo eso en riesgo."}}$IG$::jsonb, updated_at = now() where id = '96087c64-aad7-4686-a205-a87d4e7ff669';

-- Taking a medication that could affect alertness? Tell a manager first.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Check your prescription","es":"Revisa tu medicamento recetado"},"sub":{"en":"Could it affect your alertness or coordination?","es":"¿Podría afectar tu estado de alerta o coordinación?"}},{"title":{"en":"If so, tell a manager","es":"Si es así, avísale a un gerente"},"sub":{"en":"Before your shift begins","es":"Antes de que comience tu turno"}}],"why":{"en":"A manager can only plan around what they know — a quick heads-up helps keep you and your teammates safe.","es":"Un gerente solo puede planear con lo que sabe — un aviso rápido ayuda a mantenerte seguro a ti y a tus compañeros."},"example":{"en":"Started a new prescription that makes you drowsy? Tell a manager before your shift starts, not halfway through it.","es":"¿Empezaste un medicamento recetado que te da sueño? Avísale a un gerente antes de que empiece tu turno, no a la mitad."}}$IG$::jsonb, updated_at = now() where id = '4d2e8b3e-b853-4624-8402-f476d07e0de8';

-- Never possess, sell, or distribute illegal substances on Company property.
update handbook_cards set infographic = $IG${"type":"icon","icon":"alert","phrase":{"en":"Possession alone counts","es":"La posesión por sí sola cuenta"},"sub":{"en":"Not just selling or distributing — having illegal substances on Company property is enough.","es":"No solo vender o distribuir — tener sustancias ilegales en propiedad de la Compañía es suficiente."},"note":{"en":"Possessing, selling, or distributing will result in immediate termination and referral to law enforcement.","es":"Poseer, vender o distribuir resultará en terminación inmediata y referencia a las autoridades."},"noteTone":"warn","why":{"en":"Illegal substances on our property put the team, our guests, and the business at real risk.","es":"Las sustancias ilegales en nuestra propiedad ponen en riesgo real al equipo, a nuestros clientes y al negocio."}}$IG$::jsonb, updated_at = now() where id = '2085e23f-8ee3-4977-a5f6-ff94f057bd9a';

-- Serve or handle alcohol? You need a Bar Card first.
update handbook_cards set infographic = $IG${"type":"icon","icon":"clipboard","phrase":{"en":"Louisiana Permit #A — required before you serve","es":"Permiso de Luisiana #A — obligatorio antes de servir"},"sub":{"en":"Get it and keep it valid. Onboarding covers how to get yours.","es":"Sácalo y mantenlo vigente. En tu incorporación te explicamos cómo obtenerlo."},"note":{"en":"No employee under 18 may serve alcohol in any capacity.","es":"Ningún empleado menor de 18 años puede servir alcohol en ninguna capacidad."},"noteTone":"warn","why":{"en":"It's the law in Louisiana — serving without a valid card puts you and the restaurant at legal risk.","es":"Es la ley en Louisiana — servir sin una tarjeta vigente te pone a ti y al restaurante en riesgo legal."},"example":{"en":"New server? Get your Bar Card before you serve your first beer or sake.","es":"¿Mesero nuevo? Obtén tu Bar Card antes de servir tu primera cerveza o sake."}}$IG$::jsonb, updated_at = now() where id = 'e87ad5a4-4178-40b4-b531-0b8559324dfa';

-- Card any guest who looks under 40.
update handbook_cards set infographic = $IG${"type":"stat","value":"40","unit":{"en":"yrs","es":"años"},"label":{"en":"The age line for carding","es":"La edad límite para pedir identificación"},"sub":{"en":"When in doubt, card. Always.","es":"En caso de duda, pide identificación. Siempre."},"icon":"users","why":{"en":"Ages are hard to guess — carding anyone who looks under 40 leaves a wide margin so no underage guest gets served.","es":"Es difícil adivinar la edad — pedir identificación a quien aparente menos de 40 deja un margen amplio para que ningún menor de edad reciba alcohol."},"example":{"en":"A guest orders a beer and looks around 35? Card them — politely, every time.","es":"¿Un cliente pide una cerveza y aparenta unos 35? Pídele identificación — con amabilidad, siempre."}}$IG$::jsonb, updated_at = now() where id = '7cac3344-bf90-4412-9f66-5989dd71faf8';

-- Don’t serve alcohol to a guest who appears visibly intoxicated.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Politely decline","es":"Declina cortésmente"}},{"title":{"en":"Notify your manager","es":"Avísale a tu gerente"}}],"note":{"en":"The liability for over-service falls on the employee and the Company — that includes you.","es":"La responsabilidad por servir de más recae en el empleado y en la Compañía — eso te incluye a ti."},"noteTone":"warn","why":{"en":"Over-serving can hurt the guest and everyone around them — and the responsibility doesn't stop with the restaurant.","es":"Servir de más puede lastimar al cliente y a quienes lo rodean — y la responsabilidad no se queda solo en el restaurante."},"example":{"en":"A guest is slurring and asks for another round? Politely say you can't serve them another, then get your manager.","es":"¿Un cliente arrastra las palabras y pide otra ronda? Dile con cortesía que no puedes servirle otra y avísale a tu gerente."}}$IG$::jsonb, updated_at = now() where id = '4579106c-5867-43b3-ac8e-822296c57883';

-- Intoxicated guest needs a safe way home? Involve your manager.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Bring in your manager to help find a safe way home","es":"Involucra a tu gerente para buscar una forma segura de llegar a casa"}],"dont":[{"en":"Let an intoxicated guest drive away when it can reasonably be prevented","es":"Permitir que un cliente intoxicado se vaya manejando si se puede prevenir razonablemente"}],"why":{"en":"A guest's safe ride home matters more than an awkward moment — and you don't have to handle it alone.","es":"Que un cliente llegue seguro a casa importa más que un momento incómodo — y no tienes que manejarlo solo."},"example":{"en":"A clearly intoxicated guest heads out with car keys in hand? Get your manager now and work on a safer ride together.","es":"¿Un cliente claramente intoxicado sale con las llaves del carro en la mano? Busca a tu gerente ahora y busquen juntos una forma más segura de irse."}}$IG$::jsonb, updated_at = now() where id = 'f01b5943-4c79-4960-95b6-e1825c64397a';


-- ════════ Job Basics ════════

-- Your job is at-will — and that works both ways.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"You","es":"Tú"},"icon":"door","lines":[{"en":"Free to resign at any time","es":"Eres libre de renunciar en cualquier momento"},{"en":"With or without cause or advance notice","es":"Con o sin causa, y con o sin aviso previo"}]},"right":{"title":{"en":"The Company","es":"La Compañía"},"icon":"users","lines":[{"en":"May end employment at any time","es":"Puede terminar el empleo en cualquier momento"},{"en":"With or without cause or advance notice","es":"Con o sin causa, y con o sin aviso previo"},{"en":"May make staffing decisions for any lawful reason","es":"Puede tomar decisiones de personal por cualquier razón legal"}]},"note":{"en":"Nothing in the handbook, a conversation, or any other document is a contract or guarantees a job for a set time.","es":"Nada en el manual, en una conversación ni en ningún otro documento crea un contrato o garantiza empleo por un tiempo específico."},"noteTone":"info","why":{"en":"At-will keeps it simple and fair: you're never locked in, and neither is the Company.","es":"A voluntad lo mantiene simple y justo: tú nunca estás atado, y la Compañía tampoco."}}$IG$::jsonb, updated_at = now() where id = '2fc36429-7b76-4642-a6de-e7ef9e0751e2';

-- Regularly working 30+ hours a week means full-time.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Full-time","es":"Tiempo completo"},"icon":"clock","lines":[{"en":"Regularly 30+ hours a week","es":"Regularmente 30+ horas a la semana"},{"en":"Eligible for applicable benefits after your 90-day introductory period","es":"Elegible para los beneficios aplicables después del período introductorio de 90 días"}]},"right":{"title":{"en":"Part-time","es":"Medio tiempo"},"icon":"calendar","lines":[{"en":"Under 30 hours a week","es":"Menos de 30 horas a la semana"},{"en":"Not eligible for benefits unless otherwise specified in writing","es":"No elegible para beneficios a menos que se especifique lo contrario por escrito"}]},"why":{"en":"Your status follows the hours you regularly work, so it's clear who qualifies for benefits.","es":"Tu estatus depende de las horas que trabajas regularmente, así queda claro quién califica para beneficios."},"example":{"en":"Regularly working five 6-hour shifts a week? That's 30 hours — full-time.","es":"¿Trabajas regularmente cinco turnos de 6 horas a la semana? Son 30 horas — tiempo completo."}}$IG$::jsonb, updated_at = now() where id = '0c79878c-beb6-4972-ae90-1573e2f505a1';

-- Seasonal and salaried roles have their own rules.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Seasonal","es":"Temporal"},"icon":"calendar","lines":[{"en":"Hired for a set period or need","es":"Contratado por un período definido o una necesidad específica"},{"en":"No standard benefits","es":"Sin beneficios estándar"},{"en":"No guaranteed work beyond that period","es":"Sin empleo garantizado más allá de ese período"}]},"right":{"title":{"en":"Salaried management","es":"Gerencia asalariada"},"icon":"clipboard","lines":[{"en":"Exempt","es":"Exentos"},{"en":"Eligible for PTO (see Section 9)","es":"Elegibles para PTO (ver Sección 9)"},{"en":"Not eligible for overtime pay","es":"No elegibles para pago de horas extra"}]},"why":{"en":"Different roles come with different terms, so it's worth knowing exactly which ones apply to you.","es":"Cada tipo de puesto tiene sus propios términos, así que vale la pena saber exactamente cuáles aplican para ti."},"example":{"en":"Hired to help through the holiday rush? That's seasonal — work isn't guaranteed once that period ends.","es":"¿Te contrataron para apoyar en la temporada de fiestas? Eso es temporal — el trabajo no está garantizado cuando termine ese período."}}$IG$::jsonb, updated_at = now() where id = '7ebc3ca8-1a3d-43cb-9303-c3d0140f24e0';

-- Every job decision is based on your work and business need.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Based on","es":"Se basan en"},"icon":"check","lines":[{"en":"Performance","es":"Desempeño"},{"en":"Qualifications","es":"Calificaciones"},{"en":"Behavior","es":"Comportamiento"},{"en":"Business need","es":"Necesidades del negocio"}]},"right":{"title":{"en":"Never based on","es":"Nunca en"},"icon":"x","lines":[{"en":"Race, color, religion, sex, pregnancy","es":"Raza, color, religión, sexo, embarazo"},{"en":"Sexual orientation, gender identity, national origin","es":"Orientación sexual, identidad de género, origen nacional"},{"en":"Age, disability, genetic information, veteran status","es":"Edad, discapacidad, información genética, estado de veterano"},{"en":"Any other characteristic protected by law","es":"Cualquier otra característica protegida por la ley aplicable"}]},"note":{"en":"Applies to hiring, scheduling, pay, advancement, discipline, and separation.","es":"Aplica a contratación, horarios, compensación, avance, disciplina y separación."},"noteTone":"info","why":{"en":"Every decision about your job should come down to your work and what the business needs — never who you are.","es":"Cada decisión sobre tu empleo debe depender de tu trabajo y de lo que el negocio necesita — nunca de quién eres."}}$IG$::jsonb, updated_at = now() where id = '6685bafb-33fa-4597-84bd-eb1a159a515d';

-- You must complete a Form I-9 — no exceptions.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Verifies your identity","es":"Verifica tu identidad"},{"en":"Verifies your legal authorization to work in the United States","es":"Verifica tu autorización legal para trabajar en los Estados Unidos"},{"en":"Provide acceptable documents within the timeframe the law requires","es":"Presenta la documentación aceptable dentro del plazo requerido por la ley"}],"badge":{"en":"Federal requirement","es":"Requisito federal"},"note":{"en":"Employment can't begin or continue without a completed and verified I-9.","es":"El empleo no puede comenzar ni continuar sin un I-9 completado y verificado."},"noteTone":"warn","why":{"en":"Federal law requires it of every U.S. employer, so it applies to everyone on the team.","es":"La ley federal se lo exige a todo empleador en los Estados Unidos, así que aplica a todo el equipo."}}$IG$::jsonb, updated_at = now() where id = '1466113e-393d-4e90-9964-5379b0943a89';

-- Your first 90 days are a two-way evaluation.
update handbook_cards set infographic = $IG${"type":"stat","value":"90","unit":{"en":"days","es":"días"},"label":{"en":"Your introductory period","es":"Tu período introductorio"},"sub":{"en":"Starts day one: you learn the role and culture; we see if it's the right long-term fit. We watch attendance, attitude, learning ability, professionalism, and teamwork.","es":"Empieza tu primer día: tú aprendes el puesto y la cultura; nosotros evaluamos si es una buena opción a largo plazo. Observamos asistencia, actitud, capacidad de aprendizaje, profesionalismo y trabajo en equipo."},"icon":"calendar","footer":{"tone":"info","text":{"en":"Completing it starts your official tenure and eligibility for standard benefits — but doesn't guarantee continued employment.","es":"Completarlo marca el inicio oficial de tu permanencia y activa la elegibilidad para los beneficios estándar — pero no garantiza empleo continuo."}},"why":{"en":"It's a fair chance for both sides: you get to know us, and we get to know how you work.","es":"Es una oportunidad justa para ambos lados: tú nos conoces a nosotros, y nosotros conocemos cómo trabajas."},"example":{"en":"Start on March 2? Your first 90 days run through May 30.","es":"¿Empiezas el 2 de marzo? Tus primeros 90 días van hasta el 30 de mayo."}}$IG$::jsonb, updated_at = now() where id = 'd0b63078-7657-47b6-a687-3cf3f209d76e';

-- In your first 90 days, standard discipline steps may not apply.
update handbook_cards set infographic = $IG${"type":"icon","icon":"clock","phrase":{"en":"Built to catch fit issues early","es":"Hecho para detectar problemas de compatibilidad temprano"},"sub":{"en":"For your benefit and ours.","es":"Para tu beneficio y el nuestro."},"note":{"en":"Not meeting expectations? You may be separated without going through the standard disciplinary process.","es":"¿No estás cumpliendo con las expectativas? Pueden separarte del empleo sin pasar por el proceso disciplinario estándar."},"noteTone":"warn","why":{"en":"If it's not the right fit, it's better for both sides to recognize that early than to drag it out.","es":"Si no es la opción correcta, es mejor para ambos lados reconocerlo temprano que alargarlo."}}$IG$::jsonb, updated_at = now() where id = 'ce6bfe0d-4f2f-4ec3-8a6e-8e42b5576f30';

-- Keep your info current — it's your responsibility.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Keep current","es":"Mantén al día"},"icon":"clipboard","lines":[{"en":"Address","es":"Dirección"},{"en":"Phone number","es":"Número de teléfono"},{"en":"Emergency contact","es":"Contacto de emergencia"},{"en":"Direct deposit banking info","es":"Información bancaria para depósito directo"}]},"right":{"title":{"en":"Update & privacy","es":"Actualización y privacidad"},"icon":"lock","lines":[{"en":"Update through Paychex","es":"Actualízala a través de Paychex"},{"en":"Or by notifying the office manager","es":"O avisándole al gerente de oficina"},{"en":"Confidential — only authorized management and ownership can access your records","es":"Confidencial — solo la gerencia autorizada y los propietarios pueden ver tus expedientes"}]},"note":{"en":"If outdated info causes payroll or communication problems, it's your responsibility to correct.","es":"Si la información desactualizada causa problemas de nómina o comunicación, es tu responsabilidad corregirla."},"noteTone":"warn","why":{"en":"Your pay and the people we'd call in an emergency both depend on this info being right.","es":"Tu pago y las personas a quienes llamaríamos en una emergencia dependen de que esta información esté correcta."},"example":{"en":"Switched banks? Update your direct deposit in Paychex right away, before a paycheck goes to the old account.","es":"¿Cambiaste de banco? Actualiza tu depósito directo en Paychex de inmediato, antes de que un pago llegue a la cuenta vieja."}}$IG$::jsonb, updated_at = now() where id = 'e6289eda-ee51-46f9-826f-dfcb5e8e660a';

-- Coming back? Rehires are treated as new hires.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"Case by case","es":"Caso por caso"},"icon":"clipboard","lines":[{"en":"Your performance record","es":"Tu historial de desempeño"},{"en":"Past documentation","es":"Documentación anterior"},{"en":"Why you left","es":"La razón de tu salida"},{"en":"Current needs","es":"Las necesidades actuales"},{"en":"Terminated for cause or left through job abandonment? You may not be eligible.","es":"¿Te despidieron por causa o te fuiste por abandono de trabajo? Puedes no ser elegible."}]},"right":{"title":{"en":"Starts over","es":"Empieza de nuevo"},"icon":"arrow","lines":[{"en":"Pay rate","es":"Tarifa de pago"},{"en":"Benefits eligibility","es":"Elegibilidad de beneficios"},{"en":"PTO accrual","es":"Acumulación de PTO"},{"en":"Just like any new hire","es":"Como cualquier empleado nuevo"}]},"note":{"en":"The exception: ownership explicitly grants prior service credit in writing.","es":"La excepción: que los propietarios otorguen explícitamente crédito por servicio anterior por escrito."},"noteTone":"info","why":{"en":"Coming back is a fresh start, so it's handled like one — fair to you and to the team that's here now.","es":"Regresar es un nuevo comienzo, así que se maneja como tal — justo para ti y para el equipo que está aquí ahora."}}$IG$::jsonb, updated_at = now() where id = '85810f4e-5763-49ab-95c1-45ef1f67a32f';


-- ════════ Who We Are ════════

-- We were feeding Baton Rouge before most people knew sushi.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"Chinese Inn & Mandarin Seafood","es":"Chinese Inn y Mandarin Seafood"},"sub":{"en":"Where the Wong family came up","es":"Donde se formó la familia Wong"}},{"title":{"en":"2003: Ichiban","es":"2003: Ichiban"},"sub":{"en":"Baton Rouge's third sushi restaurant","es":"El tercer restaurante de sushi de Baton Rouge"}},{"title":{"en":"2020: Boru Ramen","es":"2020: Boru Ramen"},"sub":{"en":"The next chapter","es":"El siguiente capítulo"}},{"title":{"en":"Today: 30+ sushi spots","es":"Hoy: más de 30 lugares de sushi"},"sub":{"en":"And people still drive across town for Ichiban","es":"Y la gente todavía cruza la ciudad para venir a Ichiban"}}],"why":{"en":"You're joining a family that's been earning Baton Rouge's loyalty for decades — every plate you serve carries that forward.","es":"Te unes a una familia que se ha ganado la lealtad de Baton Rouge por décadas — cada plato que sirves la lleva adelante."}}$IG$::jsonb, updated_at = now() where id = 'e4b3565d-0f0b-4ad7-99fa-b629db314660';

-- Our mission: world-class discipline with Wong family warmth.
update handbook_cards set infographic = $IG${"type":"steps","tone":"process","steps":[{"title":{"en":"World-class discipline","es":"Disciplina de clase mundial"},"sub":{"en":"Great food, made with the discipline of a world-class kitchen","es":"Gran comida, con la disciplina de una cocina de clase mundial"}},{"title":{"en":"Wong family warmth","es":"Calidez de la familia Wong"},"sub":{"en":"Served with the warmth of a Wong family table","es":"Servida con la calidez de una mesa de la familia Wong"}},{"title":{"en":"Guests come back","es":"Los clientes regresan"},"sub":{"en":"Experiences so genuine they return — and bring people with them","es":"Experiencias tan genuinas que regresan — y traen a más personas"}}],"note":{"en":"The foundation never changes: serve great food, create an experience guests remember, take care of your people. That's the job.","es":"La base nunca cambia: servir gran comida, crear una experiencia que los clientes recuerden y cuidar a tu gente. Ese es el trabajo."},"noteTone":"info","why":{"en":"Discipline makes the food right every time; warmth makes guests feel at home. We need both, every shift.","es":"La disciplina hace que la comida salga bien cada vez; la calidez hace que los clientes se sientan en casa. Necesitamos ambas, en cada turno."},"example":{"en":"A roll plated perfectly, served with a real smile to a regular you greet by name — that's the mission on a Tuesday night.","es":"Un rollo emplatado a la perfección, servido con una sonrisa sincera a un cliente frecuente que saludas por su nombre — esa es la misión un martes en la noche."}}$IG$::jsonb, updated_at = now() where id = '30ce9c26-f109-4185-890c-8ffc923405e8';

-- Our values aren’t slogans — they’re standards for every shift.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Authenticity","es":"Autenticidad"},{"en":"Family","es":"Familia"},{"en":"Service","es":"Servicio"},{"en":"Community","es":"Comunidad"},{"en":"Excellence","es":"Excelencia"}],"badge":{"en":"Know all 5","es":"Conoce los 5"},"note":{"en":"Know them, hold them, and carry them into every shift — they don't bend because it's busy or the team is short. If we wouldn't serve it to family, it doesn't leave the kitchen.","es":"Conócelos, cúmplelos y llévalos a cada turno — no se doblan porque haya mucho trabajo o falte gente. Si no se lo serviríamos a la familia, no sale de la cocina."},"noteTone":"info","why":{"en":"Standards that only hold on easy nights aren't standards — guests feel the difference on the busy ones.","es":"Los estándares que solo se cumplen en noches tranquilas no son estándares — los clientes notan la diferencia en las noches ocupadas."},"example":{"en":"Short a cook on a packed Saturday and a roll comes out sloppy? Remake it — if we wouldn't serve it to family, it doesn't go out.","es":"¿Falta un cocinero un sábado lleno y un rollo sale descuidado? Hazlo de nuevo — si no se lo serviríamos a la familia, no sale."}}$IG$::jsonb, updated_at = now() where id = '072d8bd0-b7d7-43be-b686-ffb4e86f1ff6';

-- Every concept is different. The standard is the same.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Ichiban Sushi — our legacy concept since 2003: sushi and hibachi","es":"Ichiban Sushi — nuestro concepto original desde 2003: sushi y hibachi"},{"en":"Boru Ramen — Louisiana's authentic ramen spot","es":"Boru Ramen — el lugar auténtico de ramen en Louisiana"},{"en":"Shokudo — all-you-can-eat sushi and ramen","es":"Shokudo — sushi y ramen todo lo que puedas comer"},{"en":"Central Hub (in development) — restaurant, bar, coffee, and gelato","es":"Central Hub (en desarrollo) — restaurante, bar, café y gelato"}],"badge":{"en":"4 concepts, one standard","es":"4 conceptos, un estándar"},"note":{"en":"Some policies vary by concept — your manager will tell you what applies at your restaurant.","es":"Algunas políticas varían según el concepto — tu gerente te dirá lo que aplica en tu restaurante."},"noteTone":"info","why":{"en":"Each restaurant has its own menu and feel, but guests should get the same care from us at every one.","es":"Cada restaurante tiene su propio menú y ambiente, pero los clientes deben recibir el mismo cuidado de nosotros en todos."},"example":{"en":"Hibachi at Ichiban or a bowl of ramen at Boru — different food, same care in how it's served.","es":"Hibachi en Ichiban o un tazón de ramen en Boru — comida diferente, el mismo cuidado al servirla."}}$IG$::jsonb, updated_at = now() where id = '138ac7da-a81b-45fe-82a0-1d44fe393067';

-- We run on systems, not personalities.
update handbook_cards set infographic = $IG${"type":"icon","icon":"clipboard","phrase":{"en":"The same experience, whether ownership is here or not","es":"La misma experiencia, estén o no presentes los dueños"},"sub":{"en":"Slow Tuesday or packed Saturday, first week or fifth year — same standard. How you handle busy, stressful moments is one of the main measures of your professionalism.","es":"Martes tranquilo o sábado lleno, primera semana o quinto año — el mismo estándar. Cómo manejas los momentos ocupados y estresantes es una de las principales medidas de tu profesionalismo."},"note":{"en":"When we hold you accountable, it's clear, direct, and without embarrassment. When we recognize you, you earned it.","es":"Cuando te pedimos cuentas, lo hacemos de forma clara, directa y sin avergonzarte. Cuando te reconocemos, es porque te lo ganaste."},"noteTone":"info","why":{"en":"Guests shouldn't have to hope they picked a good night — systems make great service the norm, not luck.","es":"Los clientes no deberían tener que esperar haber escogido una buena noche — los sistemas hacen que el gran servicio sea la norma, no la suerte."},"example":{"en":"Owners out of town on a slammed Friday? Same sidework, same plate checks, same greeting at the door.","es":"¿Los dueños fuera de la ciudad un viernes a reventar? Las mismas tareas de apoyo, la misma revisión de platos, el mismo saludo en la puerta."}}$IG$::jsonb, updated_at = now() where id = '0392efa9-cf23-415b-a730-951d6a18bd1a';

-- Your job isn’t done until the whole team is caught up.
update handbook_cards set infographic = $IG${"type":"dodont","do":[{"en":"Jump in when a teammate is underwater","es":"Ayuda cuando un compañero está ahogado de trabajo"},{"en":"See what needs to be done — and do it","es":"Ve lo que hay que hacer — y hazlo"},{"en":"Anticipate needs — help before teammates have to ask","es":"Anticipa las necesidades — ayuda antes de que tus compañeros tengan que pedirlo"}],"dont":[{"en":"Stop because your own section is covered","es":"Detenerte porque tu sección ya está cubierta"},{"en":"Wait to be told","es":"Esperar a que te lo digan"}],"why":{"en":"Guests don't see sections — they see one team. When one of us falls behind, the whole room feels it.","es":"Los clientes no ven secciones — ven un solo equipo. Cuando uno de nosotros se atrasa, todo el salón lo siente."},"example":{"en":"Your tables are set and a teammate just got three tables at once? Run their drinks or bus their tables — before they ask.","es":"¿Tus mesas están listas y a un compañero le sentaron tres mesas a la vez? Lleva sus bebidas o recoge sus mesas — antes de que te lo pida."}}$IG$::jsonb, updated_at = now() where id = 'a27e550d-90bd-4768-b1c1-cee70fa2b69e';

-- Raises and promotions come from how you work, not just how long.
update handbook_cards set infographic = $IG${"type":"checklist","items":[{"en":"Consistency","es":"Consistencia"},{"en":"Attitude","es":"Actitud"},{"en":"Willingness to develop","es":"Ganas de desarrollarte"}],"badge":{"en":"What growth is based on","es":"En qué se basa tu crecimiento"},"note":{"en":"We promote from within whenever possible. Take feedback and correction as a tool to improve — not a personal critique.","es":"Promovemos internamente siempre que es posible. Toma la retroalimentación y la corrección como una herramienta para mejorar, no como una crítica personal."},"noteTone":"info","why":{"en":"The people who lead our teams should be the ones who've shown how they work, shift after shift.","es":"Quienes lideran nuestros equipos deben ser quienes han demostrado cómo trabajan, turno tras turno."},"example":{"en":"Coached on your sidework once and it's been spotless ever since? That's the willingness to develop we look for.","es":"¿Te corrigieron una vez en tus tareas de apoyo y desde entonces están impecables? Esas son las ganas de desarrollarte que buscamos."}}$IG$::jsonb, updated_at = now() where id = '9754ce9b-d2db-4754-b83e-48bf417de385';

-- The handbook isn’t a formality — ask when something’s unclear.
update handbook_cards set infographic = $IG${"type":"icon","icon":"book","phrase":{"en":"Our operating manual — how we run our restaurants and carry ourselves","es":"Nuestra guía operativa — cómo manejamos nuestros restaurantes y cómo nos conducimos"},"sub":{"en":"We'd rather answer your questions now than fix a misunderstanding later. The handbook will be updated as we grow, and you'll be notified of changes.","es":"Preferimos responder tus preguntas ahora que resolver un malentendido después. El manual se actualizará conforme crezcamos, y se te notificará cuando haya cambios."},"note":{"en":"The handbook is a guide, not an employment contract — it doesn't guarantee employment for any period of time.","es":"El manual es una guía, no un contrato de empleo — no garantiza empleo por ningún período de tiempo."},"noteTone":"info","why":{"en":"Clear expectations are fair expectations — you shouldn't have to guess how we do things.","es":"Las expectativas claras son expectativas justas — no deberías tener que adivinar cómo hacemos las cosas."},"example":{"en":"Not sure how an attendance rule applies to your schedule? Ask your manager now, not after it becomes a problem.","es":"¿No sabes cómo aplica una regla de asistencia a tu horario? Pregúntale a tu gerente ahora, no cuando ya sea un problema."}}$IG$::jsonb, updated_at = now() where id = '2d3212b7-c2ac-4bf4-bb93-2b3a3d1f6de8';

-- We don’t expect perfection. We expect effort and honesty.
update handbook_cards set infographic = $IG${"type":"compare","left":{"title":{"en":"What you bring","es":"Lo que traes"},"icon":"hand","lines":[{"en":"Effort","es":"Esfuerzo"},{"en":"Honesty","es":"Honestidad"},{"en":"Willingness to get better when corrected","es":"Disposición de mejorar cuando te corrigen"}]},"right":{"title":{"en":"What's here for you","es":"Lo que hay para ti"},"icon":"growth","lines":[{"en":"A place for you here","es":"Un lugar para ti aquí"},{"en":"A future worth working toward","es":"Un futuro por el que vale la pena trabajar"}]},"note":{"en":"Our standards exist to protect everyone — not to control anyone. If they're repeatedly ignored, accountability will follow.","es":"Nuestros estándares existen para proteger a todos, no para controlar a nadie. Si se ignoran repetidamente, tendrás que rendir cuentas."},"noteTone":"warn","why":{"en":"Everyone makes mistakes — what we can build on is someone who owns them and keeps getting better.","es":"Todos cometemos errores — con lo que podemos construir es con alguien que los reconoce y sigue mejorando."},"example":{"en":"Sent out the wrong roll? Say so right away and fix it — that's the honesty we mean.","es":"¿Mandaste el rollo equivocado? Dilo de inmediato y corrígelo — esa es la honestidad de la que hablamos."}}$IG$::jsonb, updated_at = now() where id = '8688fffe-7ecb-4aef-afc3-96c3b3a9f32f';


-- ── Result (should read 120 of 120) ───────────────────────────────
select count(*) filter (where infographic is not null) as cards_with_infographic,
       count(*) as total_cards
from handbook_cards
where active = true;
